\subsection{Theoretical Results}
\label{sec:previous_results}
%-----------------------------------------
Below, we provide a set-theoretical representation of simplicial complexes, and we give an alternative formulation to the FRC. This derivation used the disjoint union $N_\alpha = P_\alpha \sqcup T_\alpha$ and the result $|T_\alpha|=(d+1)|H_\alpha|$, where $N_\alpha$, $T_\alpha$ and $P_\alpha$ are the sets of neighbours, transverse neighbours and parallel neighbours to $\alpha$, respectively. Using elementary algebra, we simplify the computation for FRC to
%
\begin{eqnarray}
\label{eq:previous_formula_FRC_demonstration}
\mathrm{F}(\alpha)=(d+2)\cdot|H_{\alpha}| + 2\cdot(d+1) - |N_\alpha|,
\end{eqnarray}
%
where $N_\alpha$ is the set of neighbors of $\alpha$.
We also obtain that
%
\begin{eqnarray}\label{eq:N_set_theoretic}
   N_\alpha=\bigsqcup_{\substack{\gamma\in\partial(\alpha) \\ x\in\pi_\gamma\neq \emptyset\\x\notin\alpha}}\{\gamma\cup\{x\}\},
\end{eqnarray}
%
 and hence, we can rewrite $|N_\alpha|$ as
\begin{eqnarray}\label{eq:new_neighborhood}
    |N_\alpha|=\sum_{\gamma \in \partial \alpha}|\pi_\gamma|-(d+1). 
\end{eqnarray}
%
Finally we derive the number of $(d+1)$-cells containing $\alpha$ as
%
\begin{eqnarray}\label{eq:higher_order_cells}
|H_\alpha|=|\bigcap_{\gamma \in \partial \alpha}\pi_\gamma|.
\end{eqnarray}
%
Equations~\eqref{eq:new_neighborhood} and~\eqref{eq:higher_order_cells} together with~\eqref{eq:previous_formula_FRC_demonstration} provide a new formulation for FRC computation, namely:
%
\begin{eqnarray}\label{eq:new_formula_FRC_demonstration}
    \mathrm{F}(\alpha)=(d+2)\cdot|\bigcap_{\gamma \in \partial \alpha}\pi_\gamma|+2\cdot (d+1)-\sum_{\gamma \in \partial \alpha}|\pi_\gamma|.
\end{eqnarray}
%
This last formulation is crucial in the implementation of our novel FRC algorithm as a function of cutoff distance.
