\begin{algorithm}
\caption{Compute Local and Global Forman-Ricci Curvature (FRC)}
\label{alg:FRC}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Distance matrix $D$, maximum dimension $d_{\max}$, maximum distance $\mathrm{max\_dist}$, precision $p$
\STATE \textbf{Output:} Average local FRC and total FRC for nodes $V$
\STATE

% Step 1: Initialize parameters
\STATE Initialize node set $V$ with $|V|$ nodes (if not provided, assume $V = \{0,1, \ldots, |D|\}$)
\STATE Set cutoff step size $\delta \leftarrow 10^{-p}$ and compute $\mathrm{cutoffs} \leftarrow [0, \mathrm{max\_dist}]$ with step $\delta$
\STATE Initialize: 
\STATE $\mathrm{C}_d \leftarrow 0$, $\mathrm{F}_d \leftarrow 0$ (global curvature), $\mathrm{nF}_d(x) \leftarrow 0 \, \forall x \in V$
\STATE $\mathrm{Neighborhood} \, N_d \leftarrow \{\}$ for $d \in \{1, \dots, d_{\max}\}$

% Step 2: Generate cliques and compute FRC
\STATE \textbf{if} $d_{\max} = 1$:
    \STATE \quad Generate edge list $E$ and corresponding distances $w_{ij}$ sorted by increasing order
\STATE \textbf{else:}
    \STATE \quad Use \texttt{cliques\_gudhi} to generate cliques $\alpha$ with $w_{\alpha} \leq \mathrm{max\_dist}$
\STATE

\FOR{each clique $\alpha$ with weight $w_\alpha$}
    \STATE $d \leftarrow |\alpha| - 1$ \COMMENT{Dimension of the clique}
    \STATE $\mathrm{C}_d \leftarrow \mathrm{C}_d + 1$ \COMMENT{Count the clique}

    % Step 3: Update boundary neighborhoods
    \STATE Compute boundary $\partial(\alpha) \leftarrow \{B \,|\, B \subset \alpha, |B| = d\}$
    \FOR{each boundary $B \in \partial(\alpha)$}
        \STATE Update $\mathrm{Neighborhood}$: $N_d[B] \leftarrow N_d[B] \cup (\alpha \setminus B)$
    \ENDFOR

    % Step 4: Compute FRC for the clique
    \STATE Compute $H \leftarrow \bigcap_{B \in \partial(\alpha)} N_d[B]$ \COMMENT{Intersection of neighbors of boundaries}
    \STATE Compute total neighbors $n \leftarrow \sum_{B \in \partial(\alpha)} |N_d[B]|$
    \STATE Compute curvature: $\mathrm{f}_d \leftarrow (d+2) \cdot |H| + 2 \cdot (d+1) - n$

    % Step 5: Update local FRC for nodes
    \FOR{each node $x \in \alpha$}
        \STATE $\mathrm{nF}_d(x) \leftarrow \mathrm{nF}_d(x) + \mathrm{f}_d / (d+1)$
    \ENDFOR

    % Step 6: Update FRC for boundary nodes and neighborhoods
    \FOR{each boundary $B \in \partial(\alpha)$}
        \FOR{each node $x \in N_d[B] \setminus \alpha$}
            \STATE Compute $\delta \leftarrow \delta(x \in H, d)$ \COMMENT{Transverse or parallel neighbor}
            \FOR{each node $y \in B$}
                \STATE $\mathrm{nF}_d(y) \leftarrow \mathrm{nF}_d(y) + \delta / (d+1)$
            \ENDFOR
            \STATE $\mathrm{nF}_d(x) \leftarrow \mathrm{nF}_d(x) + \delta / (d+1)$
            \STATE Update total curvature: $\mathrm{f}_d \leftarrow \mathrm{f}_d + \delta$
        \ENDFOR
    \ENDFOR

    \STATE Update global curvature: $\mathrm{F}_d \leftarrow \mathrm{F}_d + \mathrm{f}_d$

    % Step 7: Print or store results when cutoff changes
    \IF{cutoff $w_\alpha$ changes from previous $w$}
        \IF{$\mathrm{C}_d > 0$}
            \STATE Output: $(w, \mathrm{C}_d / \mathrm{combs}_d, \mathrm{F}_d / \mathrm{C}_d, \{\mathrm{nF}_d(x) / \mathrm{C}_d, \forall x \in V\})$
        \ELSE
            \STATE Output: $(w, 0, 0, \{0, \forall x \in V\})$
        \ENDIF
        \STATE Update $w \leftarrow w_\alpha$
    \ENDIF
\ENDFOR

% Step 8: Finalize results
\STATE Fill in missing cutoff results by interpolating last valid curvature values
\STATE Return final FRC values: Average local FRC and total FRC for nodes
\end{algorithmic}
\end{algorithm}
%
%
The~\cref{alg:randomizer} was used to randomize $n$-dimensional point cloud data so that the original statistics of the points are maintained (with an error of $0.1$). In particular, it was used to randomize the Datasaurus dataset (see~\cref{fig:datasaurus_dataset}), where $n=2$, $\text{scale}=0.5$ and $\text{temp}=1$. It is worth noting that the algorithm performs several steps of point randomization in its iterations, however, they are not always effective as the randomization is not performed when the statistical conditions are not reached in that specific iteration. Therefore, a high number of total steps must be performed in order to effectively randomize the data. For instance, in \autoref{fig:FRC_and_datasaurus_itertions}, a total of $90000$ iterations were performed to obtain that $17469$ sequential iterations provide effective data randomization.
%
\begin{algorithm}
\caption{Dataset Perturbation}
\label{alg:randomizer}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Initial dataset $\text{initial\_ds}$, Number of iterations $\text{iterations}$, Temperature $\text{temp}$ , Perturbation $\text{scale}$.
\STATE \textbf{Output:} Final dataset $\text{current\_ds}$ with preserved statistical properties

\STATE

\STATE Set $\text{current\_ds} \leftarrow \text{initial\_ds}$

\STATE

\STATE \textbf{Function} \textsc{FIT}$(\text{ds})$:
\STATE \hspace{1em} \textbf{Return} the sum of distances from the origin for all points in $\text{ds}$

\STATE

\STATE \textbf{Function} \textsc{ISERROROK}$(\text{test\_ds}, \text{initial\_ds})$:
\STATE \hspace{1em} Calculate the mean and standard deviation for each coordinate in $\text{initial\_ds}$ and $\text{test\_ds}$
\STATE \hspace{1em} Calculate the correlation matrices for $\text{initial\_ds}$ and $\text{test\_ds}$
\STATE \hspace{1em} Round all values to 3 decimal places
\STATE \hspace{1em} \textbf{Return} True if means, standard deviations, and correlations match to 3 decimal places; otherwise, return False

\STATE

\STATE \textbf{Function} \textsc{MOVERANDOMPOINTS}$(\text{ds})$:
\STATE \hspace{1em} Create a copy of $\text{ds}$ as $\text{test\_ds}$
\STATE \hspace{1em} Select a random index $\text{idx}$ from $\text{ds}$
\STATE \hspace{1em} Generate a random movement vector from a normal distribution with small-scale
\STATE \hspace{1em} Move the point at $\text{test\_ds}[\text{idx}]$ by the movement vector
\STATE \hspace{1em} \textbf{Return} $\text{test\_ds}$

\STATE

\STATE \textbf{Function} \textsc{RANDOM}(scale):
\STATE \hspace{1em} \textbf{Return} a random value between 0 and 1 (with standard deviation = scale)

\STATE

\STATE \textbf{Function} \textsc{PERTURB}$(\text{ds}, \text{temp})$:
\STATE \hspace{1em} \textbf{Loop} until a valid perturbation is found:
\STATE \hspace{2em} $\text{test} \leftarrow \textsc{MOVERANDOMPOINTS}(\text{ds})$
\STATE \hspace{2em} \textbf{If} $\textsc{FIT}(\text{test}) > \textsc{FIT}(\text{ds})$ \textbf{or} $\text{temp} > \textsc{RANDOM()}$:
\STATE \hspace{3em} \textbf{Return} $\text{test}$

\STATE

\STATE \textbf{Main Function} \textsc{SimulatedAnnealing}$(\text{initial\_ds}, \text{iterations}, \text{temp})$:
\STATE \hspace{1em} Set $\text{current\_ds} \leftarrow \text{initial\_ds}$

\STATE \hspace{1em} \textbf{For} each iteration in $1$ to $\text{iterations}$:
\STATE \hspace{2em} $\text{test\_ds} \leftarrow \textsc{PERTURB}(\text{current\_ds}, \text{temp})$
\STATE \hspace{2em} \textbf{If} \textsc{ISERROROK}$(\text{test\_ds}, \text{initial\_ds})$:
\STATE \hspace{3em} Update $\text{current\_ds} \leftarrow \text{test\_ds}$

\STATE \hspace{1em} \textbf{Return} $\text{current\_ds}$

\end{algorithmic}
\end{algorithm}
