\subsection{Main results and Demonstrations}
\label{sec:demonstrations}
%-------------------------------------------------------------
In this section, we develop the theoretical assumptions of our work.
\begin{prop}\label{prop:before_after}
    Let $\alpha_i \in C_d$, $\alpha \in N^i$. Let $\mathrm{F}:C_d\rightarrow \mathbb{Z}$ and $\mathrm{F}^i$ be the FRC function as defined in \ref{eq:original_FRC}. If $\alpha$ is parallel to $\alpha_i$, then $\mathrm{F}^i(\alpha)=\mathrm{F}^{i-1}(\alpha)-1$. Otherwise, we have  $\mathrm{F}^i(\alpha)=\mathrm{F}^{i-1}(\alpha)+(d+1)$.
\end{prop}
\begin{proof}
   We have that  $F^{i-1}(\alpha)=|H^{i-1}_{\alpha}|+(d+1)-|P^{i-1}_\alpha|$. Suppose that $\alpha$ is parallel to $\alpha_i$. Thus, $P^i_\alpha=P^{i-1}_{\alpha}\sqcup\{\alpha_i\}$, which implies that $|P^{i}_{\alpha}|=|P^{i-1}_{\alpha}|+1$ and that $H^{i}_\alpha=H^{i-1}_{\alpha}$. It follows that $\mathrm{F^i}(\alpha)=|H^{i}_{\alpha}|+(d+1)-|P^{i}_\alpha|=|H^{i-1}_{\alpha}|+(d+1)-|P^{i-1}_\alpha|-1=\mathrm{F^{i-1}}(\alpha)-1.$ Suppose that $\alpha \notin P^{i+1}.$ Then, $\alpha \in T^{i+1},$ which implies that $|H^{i}_\alpha|=|H^{i-1}_\alpha|+1$ and $P^{i}_{\alpha}=P^{i-1}_{\alpha}.$ It follows that $\mathrm{F}^i_{\alpha}=|H^{i}_\alpha|+(d+1)-|P^{i}_\alpha|=(d+1)\cdot(|H^{i-1}_\alpha|+1) +(d+1) -|P^{i-1}_{\alpha}|=\mathrm{F}^{i-1}(\alpha)+(d+1).$
\end{proof}
\begin{theorem}[Geometric Gauss-Bonnet Theorem]\label{theo:Geometric_Gauss_Bonnet}
    Let $C_d$ be a non-empty set of $d$-faces in a simplicial complex $C$ generated from an undirected graph $G=(V,E)$. Let $F_d$ and $f_d$ be the global and local FRC definitions, as defined in \eqref{eq:avg_FRC} and \eqref{eq:local_total_forman}, respectively. Then, the following equality holds:
  \begin{eqnarray}
    \mathrm{F}_d(C)=\sum_{x\in V} \mathrm{f}_d(x).
\end{eqnarray}
\end{theorem}
\begin{proof}
    It is sufficient to notice that
    \begin{eqnarray}
        \sum_{x \in V}\sum_{\substack{\alpha \subset C_d \\ x \in \alpha}} \mathrm{F}_d(
\alpha)=(d+1)\sum_{\alpha \subset C_d}\mathrm{f}_d(\alpha),
\end{eqnarray}
once that for each $\alpha \in C_d$, the value $\mathrm{f}_d(\alpha)$ is counted exactly $(d+1)$ times in the sum over all the nodes $x \in V$. The result follows by multiplying both sides of the equation above by $\frac{1}{(d+1)\cdot |C_d|}$. %\autoref{fig:datasaurus_dataset} shows the 2D plots of the Datasaurus dataset.
\end{proof}
