\begin{figure}[!h]
    \centering
    \includegraphics[width=\linewidth]{figs/Examples/adding_example.png}
    \caption{Example of an evolving simplicial complex (by adding a new face) and how it influences the FRC (the numerical values given in the figure) for edges (blue) and triangles (green). The new edge has $4$ neighbours, of which two are transverse (the neighbours sharing the same triangle) and $2$ parallel (The ones outside the triangle). The $1$-FRC of the new edge is the number of triangles containing the new edge plus the length of the boundary minus the number of parallel neighbours, \textit{i.e.,} $1+2-2=1.$ When a new edge is added, the FRC increases by 2 units when a new triangle is created and decreases by 1 unit for the new neighbours outside the new triangle. Similarly, the new triangle has $3$ neighbours, where $1$ shares a tetrahedron and $2$ are parallel neighbours, therefore, the $2$-FRC of the new triangle is $1+3-2=2$. Similarly, for triangle faces, the FRC increases by 3 units when a new tetrahedron is created in the neighbourhood and decreases by 1 unit otherwise.} 
    \label{fig:example_adding_face}
\end{figure}
