\noindent\textbf{Multi-Prompt Fusion (MPF) Mechanism.} Directly adding conditional prompts into contextual prompts is insufficient for fully capturing the knowledge embeddings in the conditional prompts. In this paper, we propose a Multi-Prompt Fusion (MPF) mechanism that leverages multi-head self-attention in the VLMs' encoder to capture complex relationships and interactions among conditional prompts, contextual prompts, and word embeddings or patch embeddings across different attention heads, effectively fusing SCP and VCP with their corresponding text and visual contextual prompts, thereby enhancing the learning and modeling of class embeddings and instance-specific knowledge. Specifically, to merge features from different tokens provided by MLLMs and generate more informative combined feature representations, $P_{\mathcal{TD}}^{i}$ and the text contextual prompt $P_{\mathcal{T}}^{i} \in \mathbb{R}^{m \times d_{\text{vlms-text}}}$ can be extended to $\overline{P}_{\mathcal{TD}}^{i} \in \mathbb{R}^{1 \times n \times d_{\text{vlms-text}}}$ and $\overline{P}_{\mathcal{T}}^{i} \in \mathbb{R}^{m \times 1 \times d_{\text{vlms-text}}}$, respectively. The same applies to $P_{\mathcal{VC}}^{i}$ and the visual contextual prompts $P_{\mathcal{V}}^{i} \in \mathbb{R}^{m \times d_{\text{vlms-img}}}$. This allows for enhanced contextual prompts through broadcasting, summing, and averaging different tokens:
\begin{equation}
P_{\mathcal{TA}}^{i} = \frac{1}{n} \sum_{j=0}^{n} \left ( \overline{P}_{\mathcal{T}}^{i} + \overline{P}_{\mathcal{TD}}^{i} \right )
,P_{\mathcal{VA}}^{i} = \frac{1}{n} \sum_{j=0}^{n} \left ( \overline{P}_{\mathcal{V}}^{i} + \overline{P}_{\mathcal{VC}}^{i} \right )
\label{eq:PG-Fusion}
\end{equation}
We then extend the semantic conditional prompt $P_{\mathcal{TD}}^{i}$ along the class dimension and concatenate it with $P_{\mathcal{TA}}^{i} \in \mathbb{R}^{m \times d_{\text{vlms-text}}}$, word embeddings $\{{w}_l|_{l=1}^{L}\}$, start token embeddings ${w}_{SOS}$ and end token embeddings ${w}_{EOS}$. The visual conditional prompt $P_{\mathcal{VC}}^{i}$ is directly concatenated with $P_{\mathcal{VA}}^{i} \in \mathbb{R}^{m \times d_{\text{vlms-img}}}$ and image patch embeddings $E_{0} = \{v_{1}, v_{2}, ...v_{M}\}$, $M$ denotes the number of patches of image $I_x$. Consequently, Our new text embeddings $W_{i}^{\textrm{mllms}}$ and patch embeddings $E_{i}^{\textrm{mllms}}$ are represented as follows:
\begin{equation}
\begin{aligned}
& W_{i}^{\textrm{mllms}} = \{{w}_{SOS}, P_{\mathcal{TA}}^{i},{w}_{1}, \cdots, {w}_{L}, P_{\mathcal{TD}}^{i}, {w}_{EOS}\}  \\
& E_{i}^{\textrm{mllms}} = \{v_{1}, v_{2}, \cdots, v_{M}, P_{\mathcal{VC}}^{i}, P_{\mathcal{VA}}^{i}\}
\label{eq:PG-Wi-Ei}
\end{aligned}
\end{equation}
Ultimately, the image feature $F^{\ast } = \mathcal{V}_{i}(E_{i-1}^{\text{mllms}})$ and text feature $T^{\ast } = \mathcal{T}_{i}(W_{i-1}^{\text{mllms}})$ are obtained through the image encoder $\mathcal{V}_{i}$ and text encoder $\mathcal{T}_{i}$ for prediction:
\begin{equation}
\label{eq:PG-pre}
\mathcal{P} = \frac{\exp{( d(F^{\ast } \cdot T^{\ast }) / \tau)}}{\sum_{k=1}^{K}\exp{( d(F^{\ast } \cdot T^{\ast }_{j}) / \tau)}}
\end{equation}
where $\tau$ is temperature and $d(\cdot)$ is cosine similarity.

