\title{
	Analysing Design Approaches for the Power Consumption in Cyber-Physical Systems}

\author[1]{Patrizia Sailer}
\author[1, 2]{Igor Ivkic}
\author[1]{Markus Tauber}
\author[3]{Andreas Mauthe}
\author[2]{Antonios Gouglidis}
\affil[1]{{\normalsize \textit{University of Applied Sciences Burgenland} - Eisenstadt, Austria}}
