To complete the definition of~$G'$, we distinguish between three non-exclusive cases:
\begin{itemize}
\item \even{If~$\Delta$ is even, we turn the set~$X$ of all central vertices into a clique in~$G'$.}
\item \constant{If~$\Delta = 4$, we additionally add three vertices~$c_1,c_2$, and~$c_3$ to~$G'$ and add edges, such that~$N_{G'}[c_i] = \{c\} \cup X \cup \{c_1,c_2,c_3\}$ for each~$i\in \{1,2,3\}$.}
\item \odd{If~$\Delta$ is odd, we add the vertices~$\widehat{X} := \{\widehat{x} \mid x\in X\}$ to~$G'$ and making each vertex of~$\widehat{X}$ adjacent to each vertex of~$X \cup \widehat{X}$ in~$G'$.}
\end{itemize}
This completes the construction of~$I$.
In the following, let~$D$ be the distance matrix of~$G'$.

\subparagraph{Intuition.}
The intuitive idea is that for each edge~$\{u,v\}\in E$, the path~$(u,c,v)$ (resp.~$(v,c,u)$) is the only path of length less than~$\Delta + 1 > \alpha \cdot D_{u,v} = 2 \cdot \alpha$ from~$u$ ($v$) to~$v$ ($u$) in~$G'$.
Hence, each labeling~$\lambda$ of~$G'$ of stretch at most~$\alpha$ has to assign distinct labels to the edges~$\{c,u\}$ and~$\{c,v\}$.
In other words, if labeling~$\lambda$ of~$G'$ has stretch at most~$\alpha$, then the edges between~$c$ and the vertices of~$V$ imply a~$\Delta$-coloring for~$G$.
From these~$\Delta$ colors, only 3 can actually be assigned to the vertices of~$V$, since each of the edges from~$c$ to vertices of~$V^*$ will receive a unique label.
We now show that~$G$ is~$3$-colorable if and only if~$I$ is a yes-instance of~\STGR.
\subparagraph{Correctness.}
First, we show the forwards direction.
\begin{lemma}\label{correctness if part}
$G$ is~$3$-colorable if~$I$ is a yes-instance of~\STGR
\end{lemma}
\begin{proof}
Let~$\lambda\colon E' \to [1,\Delta]$ be an edge labeling of~$G'$ with stretch at most~$\alpha$.
First, we show that there is a set~$L'\subseteq [1,\Delta]$ of size at most three, such that for each vertex~$v\in V$, $\lambda(\{c,v\}) \in L'$.
To this end, we show that for each~$i\in [1,\Delta-3]$, the edge~$\{v^*_i,c\}$ is the only edge incident with~$c$ of label~$\lambda(\{v^*_i,c\})$.
This then implies that~$\lambda(\{v^*_i,c\}) \notin L'$ for each~$i\in [1,\Delta-3]$, which then results into~$L'$ having size at most~$3$.
Let~$w$ be an arbitrary vertex of~$(V^* \cup V) \setminus \{v^*_i\}$.
Since~$v^*_i$ and~$w$ have distance exactly~$2$, there is a path of duration less than~$\Delta + 1$ by the fact that~$\alpha \cdot D_{v^*_i,w} <  2 \cdot D_{v^*_i,w} =2 \cdot \hd[+1] =  \Delta+1$.
By construction, $P:=(v^*_i,c,w)$ is the only path from~$v^*_i$ to~$w$ of length (and thus duration) less than~$\Delta+1 > \alpha \cdot D_{v^*_i,w}$.
For~$P$ to have duration less than~$\Delta+1$, the edges~$\{v^*_i,c\}$ and~$\{w,c\}$ receive distinct labels under~$\lambda$.
Since vertex~$w$ was chosen arbitrarily, this implies that edge~$\{v^*_i,c\}$ is the only edge incident with~$c$ of label~$\lambda(\{v^*_i,c\})$.
This further concludes that~$L'$ has size at most~$3$.

We now define a $3$-coloring~$\chi\colon V \to L'$ as follows:
For each vertex~$v\in V$, we set~$\chi(v) := \lambda(\{c,v\})$.
Next, we show that for each edge~$\{u,v\}\in E$, $u$ and~$v$ receive distinct colors under~$\chi$.
Since~$\{u,v\}$ is an edge of~$E$, there is no sunglasses gadget with docking points~$u$ and~$v$ in~$G'$.
This implies that $(u,c,v)$ is the only path from~$u$ to~$v$ in~$G'$ of length less than~$\Delta+1 > \alpha \cdot D_{u,v}$.
Assume towards a contradiction that~$\chi(u) = \chi(v)$.
This would imply that~$\lambda(\{c,u\}) = \lambda(\{c,v\})$.
Hence, the unique path~$(u,c,v)$ from~$u$ to~$v$ in~$G'$ of length less than~$\Delta+1$ has a duration of exactly~$\Delta + 1 > 2 \cdot \alpha = \alpha \cdot D_{u,v}$.
This contradicts the assumption that~$\lambda$ is an edge labeling of~$G'$ with stretch at most~$\alpha$.
Thus, $\chi(u) = \lambda(\{c,u\}) \neq \lambda(\{c,v\}) = \chi(v)$, which implies that~$\chi$ is a proper~$3$-coloring for~$G'$.
\end{proof}


It remains to show the backwards direction.
To this end, suppose that~$G$ is~$3$-colorable.
Let~$\chi\colon V \to \{1,2,3\}$ be a~$3$-coloring of~$G$.
Assume without loss of generality that each of the three colors is assigned at least once.

\subparagraph{The labeling.}
We define an edge labeling~$\lambda$ of~$G'$ of stretch~$\hd$ as follows:
Let~$$\ell_2 := \begin{cases} \hd & \Delta \text{ is even, and}\\ \hd[+1] & \text{otherwise.} \end{cases}$$
Moreover, let~$L:= \{\ell_1 := \ell_2 -1, \ell_2, \ell_3 := \ell_2 + 1\}$.
For each~$i\in [1,\ell_1-1]$, we set~$\lambda(\{c,v^*_i\}) := i$ and for each~$i\in [\ell_3+1,\Delta]$, we set~$\lambda(\{c,v^*_{i-3}\}) := i$.
For each vertex~$v\in V$, we set~$\lambda(\{c,v\}) := \ell_\chi(v)$.
For each non-edge~$\{a,b\}$ of~$G$ (that is, for each added sunglasses gadget), we label the edges of the sunglasses gadget~$S_{x,y}$ according the sunglasses labeling.
To complete the definition of~$\lambda$, we distinguish between three cases:
\begin{itemize}
\item \even{
For even~$\Delta > 4$, it remains to define the labels of the edges between the vertices of~$X$.
For each of these edges~$e$, we set~$\lambda(e) := \ell_2$.
}
\item \constant{For~$\Delta = 4$, it remains to define the labels of the edges between the vertices of~$X$ and the labels of the edges incident with the vertices~$c_1,c_2$, and~$c_3$.
Let~$i\in \{1,2,3\}$.
Recall that~$N_{G'}[c_i] = \{c\} \cup X \cup \{c_1,c_2,c_3\}$.
We set~$\lambda(\{x,c_i\}) := i$ and for each vertex~$x\in X$, we set~$\lambda(\{c_i,x\}) := \begin{cases}2 & i = 3,\text{~and}\\ 4 & \text{otherwise.}\end{cases}$

Additionally, we set~$\lambda(\{c_1,c_2\}):= 3$, $\lambda(\{c_1,c_3\}):= 2$, and~$\lambda(\{c_2,c_3\}):= 1$.
}
\item \odd{
For odd~$\Delta$, it remains to define the labels of the edges incident with the vertices of~$\widehat{X}$.
For each vertex~$\widehat{x} \in \widehat{X}$, we set~$\lambda(\{x,\widehat{x}\}) := \ell_1$.
For each other edge~$e$ incident with at least one vertex of~$\widehat{X}$, we set~$\lambda(e) := \ell_2$.
}
\end{itemize}
This completes the definition of~$\lambda$.
Next, we show that~$\lambda$ has a stretch of~$\hd \leq \alpha$.
To this end, we first observe the existence of temporal paths of duration at most~$3\cdot \hd$ between the vertices of~$V\cup Y\cup X \cup \widehat{X}$.\footnote{Recall that~$\widehat{X} = \emptyset$ for even~$\Delta$.}
Afterwards, between the vertices of~$V\cup Y\cup X \cup \widehat{X}$, we then only need to consider vertex pairs of distance 2.

\begin{lemma}\label{paths between all}
Let~$v\in V\cup Y\cup X \cup \widehat{X}$ and let~$w\in V\cup Y\cup X \cup \widehat{X}$.
There is a path of duration at most~$3\cdot \hd$ from~$v$ to~$w$.
If~$v\in V$, then (i)~the first edge of this path has label~$\Delta$ or (ii)~this path has duration less than~$\Delta$ and the first edge of this path has label~$1$.
If~$w\in V$, then the last edge of this path has label~$\Delta$.
Moreover, if any of~$v$ or~$w$ is from~$X \cup \widehat{X}$, this path has length at most~$\Delta$.
\end{lemma}

\begin{proof}
To show~\Cref{paths between all} we distinguish between even and odd~$\Delta$.
First, we consider the even case.

