\section{Subspace-constrained sketch-and-project technical proofs} \label{sec:sc-sap_proofs}
%====================================

In this section, we give the technical proofs of Lemmas~\ref{lem:update} and~\ref{lem:error_invariance} for subspace-constrained sketch-and-project from Section~\ref{sec:sc-sap}.

\begin{proof}[Proof of Lemma~\ref{lem:update}]
Given the iterate $\vx^k$ after the $k$th iteration, define $\bar{\vz} := \vx^k - \vx^{k+1}$. Then from~\eqref{eq:sc_sap}, together with the change of variables $\vw = \mB^{1/2} (\vx^k - \vx)$, we have
\begin{equation} \label{eq:opt-problem}
    \mB^{1/2} \bar{\vz} =
    \left[
    \begin{tabular}{rl}
        $\displaystyle\argmin_{\vw \in \reals^n}$ & $\vw^{\tran} \vw$ \\
        \text{such that} & $\mS \mA \mB^{-1/2} \vw = \mS(\mA \vx^k - \vb)$, \\
                         & $\mQ \mA \mB^{-1/2} \vw = \mQ(\mA \vx^k - \vb)$.
    \end{tabular}
    \right]
\end{equation}
Note that since $\mQ \mA \vx^k = \mQ \vb$, the second constraint is equivalent to $\vw \in \nullspace(\mQ \mA \mB^{-1/2})$, or $\vw = \mP \vw$.
By introducing Lagrange multipliers $\vlambda \in \reals^{\ell}$, $\vtau \in \reals^{d}$, we deduce that the optimal $\vw_{\ast} = \mB^{1/2} \bar{\vz}$ solves the first-order conditions
\begin{align*}
    \vw_{\ast}  + \mB^{-1/2} \mA^{\tran} \mS^{\tran} \vlambda + \mB^{-1/2} \mA^{\tran} \mQ^{\tran} \vtau &= \vzero, \\
    \mS \mA \mB^{-1/2} \vw_{\ast}  &= \mS(\mA \vx^k - \vb), \\
    \mP \vw_{\ast}  &= \vw_{\ast}.
\end{align*}
First, by definition of $\mP$, we have $\mP \mB^{-1/2} \mA^{\tran} \mQ^{\tran} = \vzero$.
Hence, by multiplying the first equation by $\mP$, we obtain $\mP \vw_{\ast} + \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran} \vlambda = \vzero$. By combining this with $\mP \vw_{\ast} = \vw_{\ast}$, we deduce that
\[
    \vw_{\ast} = -\mP \mB^{-1/2} \mA^{\tran} \mS^{\tran} \vlambda.
\]
Thus, $\vw_{\ast} \in \range(\mP \mB^{-1/2} \mA^{\tran} \mS^{\tran})$, which implies that $\mZ \vw_{\ast} = \vw_{\ast}$. This shows that
\begin{align} \label{eq:w-update}
    \vw_{\ast} = \mZ \vw_{\ast} &= \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran} (\mS \mA \mB^{-1/2} \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran})^{\dagger} \mS \mA \mB^{-1/2} \mP \vw_{\ast} \nonumber\\
    &= \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran} (\mS \mA \mB^{-1/2} \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran})^{\dagger} \mS(\mA \vx^k - \vb),
\end{align}
where in the last line we used that $\mP \vw_{\ast} = \vw_{\ast}$, and so $\mS \mA \mB^{-1/2} \mP\vw_{\ast} = \mS(\mA \vx^k - \vb)$. Recalling that $\vx^{k+1} = \vx^k - \mB^{-1/2} \vw_{\ast}$, the update rule~\eqref{eq:lem_update_1} follows from~\eqref{eq:w-update}.

Next, from the update rule~\eqref{eq:lem_update_1}, we obtain
\begin{align*}
    \mB^{1/2}(\vx^{k+1} - \vx^*) &= \mB^{1/2} (\vx^k - \vx^*) - \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran} (\mS \mA \mB^{-1/2} \mP \mB^{-1/2} \mA^{\tran} \mS^{\tran})^{\dagger} \mS \mA(\vx^k - \vx^*) \\
    &= \mB^{1/2} (\vx^k - \vx^*) - \mZ \mB^{1/2}(\vx^k - \vx^*),
\end{align*}
where in the last line we used $\vx^k - \vx^* = \mB^{-1/2} \mP \mB^{1/2}(\vx^k - \vx^*)$.
Indeed, since $\mQ \mA(\vx^k - \vx^*) = \mQ(\mA \vx^k - \vb) = \vzero$, we have $\mB^{1/2} (\vx^k - \vx^*) \in \nullspace(\mQ \mA \mB^{-1/2})$ and so $\mP \mB^{1/2}(\vx^k - \vx^*) = \mB^{1/2} (\vx^k - \vx^*)$.
This concludes the proof of the fixed point iteration~\eqref{eq:lem_update_2}.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:error_invariance}]
From the formula~\eqref{eq:xstar_formula} for $\vx^*$, we see that $\mB^{1/2}(\vx^0 - \vx^*) \in \range(\mB^{-1/2} \mA^{\tran})$. Furthermore, since the initial iterate solves $\mQ \mA \vx^0 = \mQ \vb$, we have $\mQ \mA(\vx^0 - \vx^*) = \mQ(\mA \vx^0 - \vb) = \vzero$, and thus $\mB^{1/2}(\vx^0 - \vx^*) \in \nullspace(\mQ \mA \mB^{-1/2}) = \range(\mP)$. Hence,
\[
    \mB^{1/2}(\vx^0 - \vx^*) = \mP \mB^{1/2}(\vx^0 - \vx^*) \in \range(\mP \mB^{-1/2} \mA^{\tran}).
\]
Next, observe that $\mB^{1/2}(\vx^k - \vx^*) \in \range(\mP)$ for all $k \geq 0$ since the subsequent iterates $\vx^k$ continue to solve $\mQ \mA \vx^k = \mQ \vb$.
From the fixed point iteration~\eqref{eq:lem_update_2} in Lemma~\ref{lem:update}, we have $\mB^{1/2}(\vx^k - \vx^*) = \mB^{1/2}(\vx^{k-1} - \vx^*) - \mZ \mB^{1/2}(\vx^{k-1} - \vx^*)$.
Since $\mZ$ is the orthogonal projector onto $\range(\mP \mB^{-1/2} \mA^{\tran} \mS^{\tran})$, it follows from induction that $\mB^{1/2} (\vx^k - \vx^*) \in \range(\mP \mB^{-1/2} \mA^{\tran})$ for all $k \geq 0$.
\end{proof}


