\section{Extension of SC-RCD for least-squares problems} \label{sec:least_squares}
%====================================

\begin{algorithm}[!htb]
\caption{SC-RCD: least squares} \label{alg:sc-rcd_ls}
\begin{algorithmic}[1]
    \Require{Matrix $\mA \in \reals^{m \times n}$, vector $\vb \in \reals^{m}$, approximation rank $d$, block size $\ell$}
    \Ensure{Approximate solution $\vx \in \reals^n$ of $\argmin_{\vx} \norm{\mA \vx - \vb}_2$, residual vector $\vr = \mA \vx - \vb \in \reals^m$}
    \State Compute pivot set $\mathcal{S} \subseteq [n]$ and $\mQ \in \reals^{m \times d}$, $\mR \in \reals^{d \times n}$ defining column-pivoted partial QR decomp. $\widehat{\mA} = \mQ \mR$, and set $\mA^{\circ} \leftarrow \mA - \widehat{\mA}$  \Comment{E.g., \cite[Alg.~6]{ChenEtAl2024}}
    \State Solve $(\mA_{:,\mathcal{S}})^{\tran} \mA \vx = (\mA_{:,\mathcal{S}})^{\tran} \vb$ for $\vx$, and compute $\vr \leftarrow \mA \vx - \vb$
    \item Compute $\mC \leftarrow ((\mA^{\tran} \mA)_{\mathcal{S},\mathcal{S}})^{\dagger} (\mA^{\tran} \mA)_{\mathcal{S},:} \in \reals^{d \times n}$
    \State Set $\vp \leftarrow \vzero_{n \times 1}$, and compute $\vp_j \leftarrow \norm{\mA^{\circ}_{:,j}}_2^2 / \norm{\mA^{\circ}}_F^2$ for $j = [n] \setminus \mathcal{S}$
    \For{$k = 1, 2, \ldots$}
        \State Sample subset $\mathcal{J} = \{ j_1, \ldots, j_\ell \}$ of $\ell$ columns with $j_1, \ldots, j_\ell \sim \vp$ i.i.d.  \label{alg:sc-rcd_ls_sampling_step}
        \State Solve $(\mA^{\circ}_{:, \mathcal{J}})^{\tran} \mA^{\circ}_{:, \mathcal{J}} \valpha = (\mA_{:, \mathcal{J}})^{\tran} \vr_{\mathcal{J}}$ for $\valpha \in \reals^\ell$
        \State $\vbeta \leftarrow \mC_{:, \mathcal{J}} \valpha \in \reals^d$
        \State $\vx_{\mathcal{J}} \leftarrow \vx_{\mathcal{J}} - \valpha$, $\vx_{\mathcal{S}} \leftarrow \vx_{\mathcal{S}} + \vbeta$
        \State $\vr \leftarrow \vr - \mA^{\circ}_{:, \mathcal{J}} \valpha$
    \EndFor
\end{algorithmic}
\end{algorithm}

In this section, we will briefly explain how the SC-RCD method can be adapted to solving the least-squares problem
\begin{equation} \label{eq:ls}
    \argmin_{\vx \in \reals^n} \norm{\mA \vx - \vb}_2, \quad \text{where } \mA \in \reals^{m \times n}.
\end{equation}
Since~\eqref{eq:ls} reduces to the solution of the normal equations $\mA^{\tran} \mA \vx = \mA^{\tran} \vb$, this can be solved by applying the psd SC-RCD method on the normal equations. In the following, we will show that the algorithm can be implemented without explicitly forming the psd matrix $\mA^{\tran} \mA$ as a column-action method; see Algorithm~\ref{alg:sc-rcd_ls} for pseudocode.

In this setting, the natural analogue of the Nystr\"{o}m approximation is the \emph{column projection approximation} $\mPi_{\mA, \mathcal{S}} \mA$ of $\mA$, where $\mPi_{\mA, \mathcal{S}}$ is the orthogonal projector onto the span of the columns of $\mA$ indexed by $\mathcal{S}$.
The key observation is that the entries of the Gram matrix $(\mA_{:,\mathcal{S}})^{\tran} \mA_{:,\mathcal{S}}$ give the inner products between the columns of $\mA$ indexed by $\mathcal{S}$; in particular, the squared column norms can be read off the diagonal (see, e.g.,~\cite[\S 3]{ChenEtAl2024} for more details on this classical connection).
Indeed, the RPCholesky algorithm can be naturally adapted to output a column projection approximation in the form of a partial QR decomposition $\widehat{\mA} = \mQ \mR$ of $\mA$, where $\mQ \in \reals^{m \times d}$ has orthonormal columns and $\mR \in \reals^{d \times n}$ is upper triangular, such that $\widehat{\mA}_{:,\mathcal{S}} = \mA_{:,\mathcal{S}}$ and $\range(\widehat{\mA}) = \range(\mA_{:,\mathcal{S}})$; see~\cite[Algorithm~6]{ChenEtAl2024}.

\paragraph{Derivation of Algorithm~\ref{alg:sc-rcd_ls}.}
Suppose that we are given a column projection approximation $\mPi_{\mA, \mathcal{S}} \mA$ of $\mA$ with pivots $\mathcal{S} \subseteq [n]$ and an initial iterate $\vx^0$ satisfying $(\mA^{\tran} \mA)_{\mathcal{S},:} \vx^0 = (\mA^{\tran} \vb)_{\mathcal{S}}$.
Let
\begin{equation} \label{eq:column_approx}
    \widehat{\mA} := \mPi_{\mA, \mathcal{S}} \mA
    \quad\text{and}\quad
    \mA^{\circ} := \mA - \widehat{\mA}
\end{equation}
be the column projection approximation of $\mA$ with respect to the columns indexed by $\mathcal{S}$ and the corresponding residual matrix respectively.
Observe that if $$\mP = \mI - (\mA^{\tran} \mA)^{1/2} \ve_{\mathcal{S}} ((\mA^{\tran} \mA)_{\mathcal{S},\mathcal{S}})^{\dagger} \ve_{\mathcal{S}}^{\tran} (\mA^{\tran} \mA)^{1/2}$$ is the orthogonal projector onto $\nullspace(\ve_{\mathcal{S}}^{\tran} (\mA^{\tran} \mA)^{1/2})$, then
\begin{equation} \label{eq:column_approx_proj}
    (\mA^{\tran} \mA)^{1/2} \mP (\mA^{\tran} \mA)^{1/2}
    = \mA^{\tran} (\mI - \mPi_{\mA, \mathcal{S}}) \mA
    = (\mA^{\circ})^{\tran} \mA^{\circ}.
\end{equation}
Hence, after some algebraic manipulations, the update~\eqref{eq:sc-rcd_update} for the iterate $\vx^k$ for solving the psd system $\mA^{\tran} \mA \vx = \mA^{\tran} \vb$ with SC-RCD is equivalent to the following:
\begin{equation} \label{eq:sc-rcd_ls_update}
    \vx^{k+1}
    = \vx^k - \ve_{\mathcal{J}} \valpha^k + \ve_{\mathcal{S}} \vbeta^k,
\end{equation}
where
\[
    \valpha^k := (((\mA^{\circ})^{\tran} \mA^{\circ})_{\mathcal{J}, \mathcal{J}})^{\dagger} (\mA_{:, \mathcal{J}})^{\tran} \vr^k
    \quad\text{and}\quad
    \vbeta^k := \mC_{:, \mathcal{J}} \valpha^k,
\]
with $\mC := ((\mA^{\tran} \mA)_{\mathcal{S},\mathcal{S}})^{\dagger} (\mA^{\tran} \mA)_{\mathcal{S},:}$.
Furthermore, the update~\eqref{eq:sc-rcd_update_resid} for the residual vector $\vr^k = \mA \vx^k - \vb$ is equivalent to
\begin{align} \label{eq:sc-rcd_ls_update_resid}
    \vr^{k+1}
    &= \vr^{k} - (\mI - \mPi_{\mA, \mathcal{S}}) \mA_{:, \mathcal{J}} \valpha^k
    = \vr^{k} - \mA^{\circ}_{:, \mathcal{J}} \valpha^k.
\end{align}
The updates~\eqref{eq:sc-rcd_ls_update} and~\eqref{eq:sc-rcd_ls_update_resid} are summarized in the pseudocode in Algorithm~\ref{alg:sc-rcd_ls}.
Each iteration requires accessing the columns of $\mA$ and $\widehat{\mA}$ indexed by the sampled block $\mathcal{J}$.
Similar to the psd case (Section~\ref{sec:sc-rcd_implementation}), the partial QR structure of the approximation $\widehat{\mA}$ can be used to compute the auxiliary matrix $\mC$ and initial iterate $\vx^0$ more efficiently.

The following result states the convergence rate of the least squares SC-RCD method (Algorithm~\ref{alg:sc-rcd_ls}), which immediately follows from Theorem~\ref{thm:sc-rcd_convrate} for a fixed pivot set $\mathcal{S}$. As in the psd SC-RCD case, this can be further combined with bounds for the quality of the low-rank approximation $\widehat{\mA}$ such as~\cite[Corollary~5.2]{ChenEtAl2024}, which we do not elaborate on.

\begin{theorem} \label{thm:sc-rcd_ls_convrate}
Let $\mA \in \reals^{m \times n}$ and $\vx^*$ be any solution of the least squares problem~\eqref{eq:ls}. Suppose that $\{ \vx^k \}_{k \geq 0}$ are the iterates defined by~\eqref{eq:sc-rcd_ls_update} with a fixed subset $\mathcal{S} \subseteq [n]$, and the block $\mathcal{J} = \{ j_1, \ldots, j_\ell \}$ in each iteration consists of $\ell$ columns independently sampled according to the distribution $\{ \norm{\mA^{\circ}_{:,j}}_2^2 / \norm{\mA^{\circ}}_F^2 \}_{j=1}^n$. Then
\[
    \E \norm{\vx^k - \vx^*}_{\mA^{\tran} \mA}^2 \leq \left( 1 - \frac{\sigma_{\mathrm{min}}^+(\mA^{\circ})^2}{\norm{\mA^{\circ}}_F^2} \right)^{k \ell} \cdot \norm{\vx^0 - \vx^*}_{\mA^{\tran} \mA}^2,
\]
where $\mA^{\circ} = \mA - \mPi_{\mA, \mathcal{S}} \mA$, and $\sigma_{\mathrm{min}}^+(\mA^{\circ})$ is the smallest non-zero singular value of $\mA^{\circ}$.
Note that $\norm{\vx^k - \vx^*}_{\mA^{\tran} \mA} = \norm{\vr^k}_2$ where $\vr^k = \mA \vx^k - \vb$ is the corresponding residual vector.
\end{theorem}


