\section{Densest Subgraph Problem Experiments}
\label{densestsubgraphexperiments}

\textbf{Problem Definition.} Given a graph $G=(V, E)$, find a vertex set $\emptyset \neq S\subseteq V$ maximizing $|E(S)|/|S|$.

\paragraph{Algorithms.} We evaluate \textit{seven} algorithms—Frank-Wolfe (\textsc{frankwolfe}, \cite{frankwolfe}), Fujishige-Wolfe Minimum Norm Point (\textsc{mnp}), and \textsc{SuperGreedy++} (\textsc{supergreedy}, \cite{flowless}), FISTA \cite{farouk-neurips}, RCDM \cite{alina}, the incremental algorithm \cite{Hochbaum2024flow}, and a new push-relabel flow-based algorithm based on the density improvement mechanism, but using push-relabel flow. 

