\item[] {\bf PN-surfaces.} A PN-surface is a rational surface with a rational normal vector field. In the case of PN-surfaces, we replace in our algorithm the equation $\mbox{ }\widehat{\bf H}_\bfx(t,s)=\widehat{\bf H}_\bfx(u,v)$ by $\mbox{ }\bf H_\bfx(t,s)=\pm\bf H_\bfx(u,v)$. This reduces the degree of the equations in the resultants. \textcolor{black}{In order to} generate non-trivial PN-surfaces we used the \textcolor{black}{strategy} given in \cite{KMV}, where the authors provide a method using quaternions. First we consider the cubic PN-surface (See Fig \ref{fig:second}) given by the following rational parametrization.

\begin{equation*}
\bfx(t,s)=\begin{pmatrix}
-\frac{1}{3} s^3 -\frac{1}{3} s^2t +\frac{7}{3} st^2 + t^3 -\frac{5}{3} s^2 +\frac{26}{3} st +\frac{25}{3} t^2 \\[3pt]
-\frac{1}{3} s^3 -\frac{5}{3} s^2t -\frac{5}{3} st^2 + t^3 -\frac{13}{3} s^2 -10 st +\frac{13}{3} t^2 -\frac{46}{3} s +\frac{2}{3} t\\[3pt]
-\frac{4}{3} s^3 - 4 s^2t -\frac{4}{3} st^2 - 4t^3 - 9s^2 +\frac{14}{3} st +\frac{5}{3} t^2 -\frac{10}{3} s +\frac{26}{3} t
\end{pmatrix}
\end{equation*}

This PN-surface has \textcolor{black}{one} projective base point, $[-3:1:0]$, and admits two symmetries corresponding to the Cremona transformations
\begin{equation*}
\left(\dfrac{3}{5}t-\dfrac{4}{5}s+\dfrac{1}{5},\dfrac{3}{5}t-\dfrac{4}{5}s-\dfrac{3}{5}\right), (t,s),
\end{equation*}
with symmetries
\begin{align*}
f_1(\bfx)&=\begin{pmatrix}
\frac{24}{25} & \frac{7}{25} & 0\\[4pt]
\frac{7}{25} & -\frac{24}{25} & 0\\[4pt]
0 & 0 & 1
\end{pmatrix}\bfx+\begin{pmatrix}
-\frac{98}{75}\\[4pt]
\frac{686}{75}\\[4pt]
0
\end{pmatrix}\\
f_2(\bfx)&=\begin{pmatrix}
1 & 0 & 0\\
0 & 1 & 0\\
0 & 0 & 1
\end{pmatrix}\bfx+\begin{pmatrix}
0\\
0\\
0
\end{pmatrix}
\end{align*}

The whole computation of this example took $0.203$ seconds. Now, \textcolor{black}{consider the} cubic PN-surface (See Fig \ref{fig:first}) given by the following rational parametrization.
\begin{equation*}
\bfy(t,s)=\begin{pmatrix}
-\frac{4}{13} s +\frac{1}{13} s^2 -\frac{11}{156} s^3 -\frac{3}{32} s^4 - \frac{4}{13} t -\frac{6}{13} ts -\frac{9}{52} ts^2 -\frac{7}{13} t^2 -\frac{9}{52} t^2s -\frac{3}{16} t^2s^2 -\frac{59}{156} t^3 -\frac{3}{32} t^4\\[3pt]
\frac{4}{13} s^2 -\frac{11}{52} s^3 +\frac{1}{8} s^4 +\frac{25}{52} ts^2 +\frac{4}{13} t^2 -\frac{1}{52} t^2s +\frac{1}{4} t^2s^2 +\frac{19}{52} t^3 +\frac{1}{8} t^4\\[3pt]
-\frac{4}{13}s + s^2 -\frac{17}{78} s^3 +\frac{3}{8} s^4 +\frac{28}{13} t -\frac{8}{13} ts +\frac{22}{13} ts^2 +\frac{37}{13} t^2 -\frac{4}{13} t^2s +\frac{3}{4} t^2s^2 +\frac{131}{78} t^3 +\frac{3}{8} t^4
\end{pmatrix}
\end{equation*}

This PN-surface has two projective base points $[\mathbf{i}:1:0]$ and $[-\mathbf{i}:1:0]$. The surface admits two symmetries corresponding to the Cremona transformations
\begin{equation*}
\left(-s-\dfrac{12}{13},-t-\dfrac{12}{13}\right), (t,s),
\end{equation*}
with symmetries
\begin{align*}
f_1(\bfx)&=\dfrac{1}{169}\begin{pmatrix}
137 & -96 & 24\\
-96 & -119 & 72\\
24 & 72 & 151
\end{pmatrix}\bfx+\dfrac{1}{28561}\begin{pmatrix}
3840\\
11520\\
-2880
\end{pmatrix}\\
f_2(\bfx)&=\begin{pmatrix}
1 & 0 & 0\\
0 & 1 & 0\\
0 & 0 & 1
\end{pmatrix}\bfx+\begin{pmatrix}
0\\
0\\
0
\end{pmatrix}
\end{align*}

The whole computation of this example took $0.125$ seconds.

