\title{Maximum Separation of Quantum Communication Complexity \\ With and Without Shared Entanglement}

\author[1]{Atsuya Hasegawa\thanks{atsuya.hasegawa@math.nagoya-u.ac.jp}}
\author[1]{Fran{\c{c}}ois Le Gall\thanks{legall@math.nagoya-u.ac.jp}}
