\section{Overall Pipeline}

To present our method’s workflow more clearly, we provide the following pseudocode.

\begin{algorithm}[H]
\caption{Overall Pipeline}
\label{alg:inference_simple}
\begin{algorithmic}[1]
\Require Global image $\mathbf{I}$, Text instruction $T_{ins}$
\Ensure Set of predicted masks $\mathcal{M}$, Generated output sequence $S_{out}$

\State $f_g, F_{pixel} \gets \text{SEFE}(\mathbf{I})$

\State $S \gets \{f_g, T_{ins}\}$
\State $\mathcal{M} \gets \emptyset$; \quad $M_{current} \gets \text{null}$

\While{not end-of-generation}
    \State $token \gets \text{LLM.generate}(S)$

    \If{$token$ is \texttt{<eos>}}
        \State \textbf{break}

    \ElsIf{$token$ is \texttt{<seg>}}
        \State $M_{current} \gets \text{PixelDecoder}(token, F_{pixel})$
        \State $\mathcal{M} \gets \mathcal{M} \cup \{M_{current}\}$
        \State $S \gets S \oplus token$
    \ElsIf{$token$ is \texttt{<image\_id>}}
        \State $I_l \gets \text{CropRegion}(\mathbf{I}, M_{current})$
        \State $f_l \gets \text{SemanticEncoder}(I_l)$
        \State $S \gets S \oplus token$
        \State $S \gets S \oplus f_l$
    \Else
        \State $S \gets S \oplus token$
    \EndIf
\EndWhile

\State $S_{out} \gets S$
\State \textbf{return} $\mathcal{M}, S_{out}$
\end{algorithmic}
\end{algorithm}


