\subsection{The structure theorem for rooted binary phylogenetic networks}\label{sec:preliminaries1}
We recall the relevant materials from \cite{Hayamizu-2021-StructureTheoremRooted}. 
Given a rooted binary phylogenetic network $N$,  a connected subgraph $Z$ of  $N$ with $m:=|E(Z)|\geq 1$  is a  \emph{zig-zag trail} (\emph{in $N$}) if the edges of $Z$ can be permuted as $(e_1, \dots, e_m)$ such that either $\head(e_i)=\head(e_{i+1})$ or $\tail(e_i)=\tail(e_{i+1})$ holds for each $i\in [1,m-1]$. 
A zig-zag trail is represented by an alternating sequence of (not necessarily distinct) vertices and distinct edges, e.g., $(v_0, (v_0, v_1), v_1, (v_2, v_1), v_2, \dots, (v_m, v_{m-1}), v_m)$, which can more concisely written as $v_0 > v_1 < v_2 > \cdots > v_{m-1} < v_m$ or its reverse. 
	A zig-zag trail $Z$ in $N$ is  \emph{maximal} if $N$ contains no zig-zag trail $Z^\prime$  such that $Z$ is a proper subgraph of $Z^\prime$. Each maximal zig-zag trail in $N$ falls into one of the following four types. 
	A \emph{crown} is a maximal zig-zag trail $Z$ that has even $m:=|E(Z)|\geq 4$ and can be written in the cyclic form $v_0 < v_1 > v_2 < v_3 > \cdots  > v_{m-2} < v_{m-1} > v_{m} = v_0$.  A \emph{fence} is any maximal zig-zag trail that is not a crown. An \emph{N-fence} is a fence $Z$ with odd $m:=|E(Z)|\geq 1$,  expressed as $v_0 > v_1 < v_2 > \cdots < v_{m-1} > v_m$. A fence $Z$ with even $m:=|E(Z)|\geq 2$ is an \emph{M-fence} if expressed as $v_0 < v_1 > v_2 < \cdots < v_{m-1} > v_m$, and it is a \emph{W-fence} if expressed as $v_0 > v_1 < v_2 > \cdots > v_{m-1} < v_m$. %Additionally, for a zig-zag trail $Z$, we call the number of edges $|E(Z)|$ the \emph{size} of $Z$. 

		As in the approach taken in \cite{Hayamizu-2021-StructureTheoremRooted, HayamizuMakino-2023-RankingTopkTrees}, we often consider a maximal zig-zag trail $Z$ as a sequence $(e_1,\dots,e_{|E(Z)|})$ of edges, ordered according to their appearance in the trail. When $Z$ is a fence, the \emph{terminal edges} of $Z$ are the first and last edges in such a sequence. 
		This representation allows us to encode any edge-induced subgraph of $Z$ as a 0-1 sequence of length $|E(Z)|$. For example, for an $N$-fence $Z = (e_1, e_2, e_3, e_4, e_5)$ and a subset $\{e_1, e_3, e_5\} \subseteq E(Z)$, the subgraph of $Z$ induced by this edge-set can be written as $\langle1\; 0\; 1\;0\;1\rangle = \langle1(01)^2\rangle$.


We now restate the structure theorem for rooted binary phylogenetic networks, which provides a way to canonically decompose such networks $N$ (see Figure \ref{fig:zigzagtrail decomposition} for an illustraction) and characterizes the family of admissible subsets $S$ of $E(N)$, namely, the family of edge-sets of support trees of $N$. 

\begin{theorem}[\cite{Hayamizu-2021-StructureTheoremRooted}]\label{thm:structure}
For any rooted binary phylogenetic network $N$, the following hold: 
\begin{enumerate}
%	\item $N$ is uniquely decomposed into its maximal zig-zag trails, each of which is a crown, M-fence, N-fence or W-fence. The maximal zig-zag trail decomposition $\mathcal{Z}=\{Z_1,\dots, Z_d\}$  of  $N$ can be computed in $O(|E(N)|)$ time. 
	\item The maximal zig-zag trail decomposition $\mathcal{Z}=\{Z_1,\dots, Z_d\}$  of  $N$ is unique to $N$. 
	\item Given $S \subseteq E(N)$, $N[S]$ is a support tree of $N$ if and only if for each $Z_i\in \mathcal{Z}$, $E(G)\cap E(Z_i)$ is an admissible subset of $E(Z_i)$. Here, the family $\mathcal S(Z_i)$ of admissible subsets of $E(Z_i)$ is given by \eqref{sequence}. 
	\item The family $\mathcal T$ of support trees of $N$ is non-empty (i.e., $N$ is tree-based) if and only if each $\mathcal{S}(Z_i)$ is non-empty (i.e., no element of $\mathcal{Z}$ is a W-fence). When $\mathcal T$ is non-empty, it is characterized by $\mathcal T=\prod_{i=1}^{d}{\mathcal S(Z_i)}$, where $(Z_1,\dots, Z_d)$ is an arbitrary ordering for $\mathcal{Z}$. 
\end{enumerate}
\begin{align}
  \label{sequence}
    \mathcal S (Z_i) = \begin{cases}
    	\emptyset & \text{if $Z_i$ is a W-fence}\\
        \{\langle 1(01)^{(|E(Z_i)|-1)/2}\rangle  \} & \text{if $Z_i$ is an N-fence}\\
        \{\langle (10)^{|E(Z_i)|/2}\rangle, \langle (01)^{|E(Z_i)|/2}\rangle \} & \text{if $Z_i$ is a crown}\\
        \{\langle 1(01)^p (10)^q 1\rangle \mid p, q\in \mathbb{Z}_{\geq 0}, p,+q = (|E(Z_i)|-2)/2 \} & \text{if $Z_i$ is an M-fence}
      \end{cases}%\label{eq:sequence for spanning tree}
\end{align}
\end{theorem}


\begin{proposition}[\cite{Hayamizu-2021-StructureTheoremRooted}]\label{prop:linear.zzt}
The maximal zig-zag trail decomposition $\mathcal{Z}$ of $N$ can be computed in $\Theta(|E(N)|)$ time. 	
\end{proposition}


