\subsection{The number $|\mathcal{A}_N|$ of all support networks}
\label{sec: all support network}
 As explained above, one can construct an $\mathcal{A}$-admissible subset of $E(N)$ simply by obeying (C1$^\star$) and (C2$^\star$) in Definition \ref{def:alpha-admissible}, namely, by selecting both terminal edges of each fence and by avoiding two consecutive unselected edges in each $Z_i$. Thus, the family $\mathcal{S}_{\mathcal{A}}(Z_i)$ of $\mathcal{A}$-admissible subsets of $E(Z_i)$ is expressed by \eqref{eq:sequence for support network} for each $Z_i\in \mathcal{Z}$.  %Recall $m_i:=|Z_i|$. 
    \begin{align}
      \mathcal{S}_{\mathcal{A}}{(Z_i)} = \begin{cases}
        \{ \langle b_1\cdots b_{|E(Z_i)|}\rangle \mid \text{$b_1 = b_{|E(Z_i)|} = 1$, $\langle 00\rangle$ is not a subsequence}\}\\
        \hfill \text{if $Z_i$ is a fence}\\
        \{  \langle b_1 \cdots b_{|E(Z_i)|}\rangle \mid \text{$\langle 00\rangle$ is not a subsequence for any ordering} \}\\
        \hfill \text{if $Z_i$ is a crown}
        \end{cases}\label{eq:sequence for support network}
    \end{align}

    By Lemma \ref{thm:bijection.ABC},  $\mathcal{A}_N$ is characterized by $\mathcal{A}_N = \prod_{i=1}^d \mathcal{S}_{\mathcal{A}} (Z_i)$. Therefore, $|\mathcal{A}_N| = \prod_{i=1}^d |\mathcal{S}_{\mathcal{A}} (Z_i)|$. As in \eqref{eq:sequence for support network}, each number $|\mathcal{S}_{\mathcal{A}} (Z_i)|$ depends on whether $Z_i$ is a fence or not. This  number can be more explicitly represented using Fibonacci and Lucas numbers (OEIS A000045 and OEIS A000032, respectively) as follows. The proof of Theorem \ref{thm:fibonacci.lucas} is given in Appendix \ref{apd.proof:fibonacci.lucas}.

%    It follows that one can count $|\mathcal{A}_N|$ simply by computing $|\mathcal{S}_\mathcal{A}(Z_i)|$ for each  $Z_i\in \mathcal{Z}$. 

  \begin{theorem}\label{thm:fibonacci.lucas}
    Let $N$ be a rooted binary phylogenetic network and $\mathcal{Z} = \{Z_1, \dots, Z_d\}$ be the maximal zig-zag trail decomposition of $N$. 
    Let $\{F_n\}$ be the Fibonacci sequence defined by $F_1 = F_2 = 1$ and $F_n = F_{n-1} + F_{n-2}$ ($n \geq 3$), and $\{L_n\}$ be the Lucas sequence  defined by $L_1 = 1, L_2 = 3$ and $L_n = L_{n-1} + L_{n-2}$ ($n\geq 3$).
    Then, the number of support networks $|\mathcal{A}_N|$ is given by \eqref{eq:count all support}. 
    \begin{align}
      \label{eq:count all support}
      |\mathcal{A}_N| = \prod_{Z_i: \text{fence}} F_{|E(Z_i)|} \cdot \prod_{Z_i: \text{crown}} L_{|E(Z_i)|}
    \end{align}
    Moreover, $|\mathcal{A}_N| = \Theta(\phi^{|E(N)|})$ holds, where $\phi = (1+\sqrt{5})/2 = 1.6180\dots$ is the golden ratio.
    % is the unique positive solution of $x^2 = x + 1$.
  \end{theorem}


