\subsection{The number $|\mathcal{B}_N|$ of minimal support networks}
\label{sec:minimal support network}
%Suppose $Z_i$ is an element of $\mathcal{Z}$ and $S\subseteq E(Z_i)$ is an $\mathcal{A}$-admissible subset. In this case, if $S$ does not contain any three consecutive edges $(e_{j-1}, e_j, e_{j+1})$ in $Z$, then $e_{j-1} \notin S$ or $e_{j+1}\notin S$ holds. This means that $S\setminus\{e_j\}$ is not $\mathcal A$-admissible whenever $e_j\in S$, which implies $S$ is $\mathcal{B}$-admissible. Conversely, if $S$ contains any three consecutive edges $(e_{j-1}, e_j, e_{j+1})$, then $S\setminus\{e_j\}$ of $S$ is also an $\mathcal A$-admissible subset of $E(Z_i)$. This means that $S$ is not minimal, namely not $\mathcal{B}$-admissible. Therefore, 
We can see that $\mathcal{A}$-admissible subset $S$ of $E(Z_i)$ is $\mathcal{B}$-admissible if and only if $S$ contains no three consecutive edges in the edge sequence $(e_1,\dots, e_{|E(Z_i)|})$ of $Z_i$. 
%In other words, when we characterize $\mathcal{S}_{\mathcal{B}}(Z_i)$ for each $Z_i\in \mathcal{Z}$ to add the minimality of the edges in $\mathcal{S}_{\mathcal{A}}(Z_i)$, it suffices to impose a forbidden subsequence $\langle 111\rangle$ in addition to the conditions in \eqref{eq:sequence for support network}.
Thus, the family $\mathcal{S}_{\mathcal{B}}(Z_i)$ of $\mathcal B$-admissible subsets of $E(Z_i)$ is expressed as in \eqref{eq:sequence for minimal support network} for each $Z_i\in \mathcal{Z}$.
\begin{align}
  \mathcal{S}_{\mathcal{B}}(Z_i) =\begin{cases}
    \{ \langle b_1\cdots b_{|E(Z_i)|}\rangle \mid \text{$b_1 = b_{|E(Z_i)|} = 1$, neither $\langle 00\rangle$ nor $\langle 111\rangle$ is a subsequence}\}\\
    \hfill \text{if $Z_i$ is a fence}\\
    \{ \langle b_1 \cdots b_{|E(Z_i)|}\rangle \mid \text{neither $\langle 00\rangle$ nor $\langle 111\rangle$ is a subsequence for any ordering} \}\\
    \hfill \text{if $Z_i$ is a crown}
    \end{cases} \label{eq:sequence for minimal support network}
\end{align}

By Lemma \ref{thm:bijection.ABC}, $\mathcal{B}_N$ is characterized by $\mathcal{B}_N = \prod_{i=1}^d \mathcal{S}_{\mathcal{B}} (Z_i)$.
Therefore, $|\mathcal{B}_N| = \prod_{i=1}^d |\mathcal{S}_{\mathcal{B}} (Z_i)|$. This number is expressed using Padovan numbers (OEIS A000931) and Perrin numbers (OEIS A001608) as follows.
The proof of Theorem \ref{thm:counting by padovan, perrin} is in Appendix \ref{apd.proof.B.padovan.perrin}. 



  \begin{theorem}\label{thm:counting by padovan, perrin}
    Let $N$ be a rooted binary phylogenetic network and $\mathcal{Z} = \{Z_1, \dots, Z_d\}$ be the maximal zig-zag trail decomposition of $N$. 
    Let $\{P_n\}$ be the Padovan sequence defined by $(P_1, P_2, P_3) = (1, 1, 1)$ and $P_n = P_{n-2} + P_{n-3}$ ($n \geq 4$), and $\{Q_n\}$ be the Perrin sequence defined by $(Q_1, Q_2, Q_3) = (0, 2, 3)$ and $Q_n = Q_{n-2} + Q_{n-3}$ ($n \geq 4$).
    Then, the number of minimal support networks $|\mathcal{B}_N|$ is given by \eqref{eq:count minimal support}. 
    \begin{align}
      \label{eq:count minimal support}
      |\mathcal{B}_N| = \prod_{Z_i: \text{fence}} P_{|E(Z_i)|} \cdot \prod_{Z_i: \text{crown}} Q_{|E(Z_i)|}
    \end{align}
    Moreover, $|\mathcal{B}_N| = \Theta(\psi^{|E(N)|})$ holds, where $\psi = \sqrt[3]{(9 +\sqrt{69})/18}+ \sqrt[3]{(9 -\sqrt{69})/18} =  1.3247\dots$ is the plastic number.
    \end{theorem}




    \begin{proposition}
    \label{prop:complexity of count minimal support network}
   $|\mathcal{B}_N|$ can be computed in $\Theta(|E(N)|)$ time. 
  \end{proposition}
  \begin{proof}
   The only difference between \eqref{eq:count all support} and \eqref{eq:count minimal support} is that $F_{|E(Z_i)|}$ and $L_{|E(Z_i)|}$ are replaced by $P_{|E(Z_i)|}$ and $Q_{|E(Z_i)|}$, respectively. For each $Z_i\in \mathcal{Z}$, both $P_{|E(Z_i)|}$ and $Q_{|E(Z_i)|}$ can also be computed in $O(|E(Z_i)|)$ time. The remainder is the same as the proof of Proposition \ref{prop:complexity.count.A}.
  \end{proof}

As noted in Section \ref{sec: all support network}, the elements of $\mathcal{B}_N$ can also be listed with $\Theta(|E(N)|)$ delay.


