    \{\langle 1(01)^p (10)^q 1\rangle \mid p, q\in \mathbb{Z}_{\geq 0}, p+q = (|E(Z_i)|-2)/2 \}\qquad\qquad\qquad\\
    \hfill \text{if $Z_i$ is an M-fence or W-fence}
