\section{Finding a support network with the fewest reticulations}\label{sec:minimum.reticulation}
As defined in Section \ref{sec:Problem}, the base tier  $r^\ast (N)$ of $N$ is the minimum value of $r(G)$ over all support networks $G$ of $N$. This leads us to Problem \ref{prob:minimum reticulation}.

\begin{problem}[\textsc{Reticulation Minimization}]
  \label{prob:minimum reticulation}
  Given a rooted binary phylogenetic network $N$, compute the base tier $r^\ast(N)$, and find a support network $G$ of $N$ with $r(G)=r^\ast(N)$.
\end{problem}

Since $r(G):=|E(G)| - |V(G)| + 1$ and  $G$ is a spanning subgraph of $N$, the support networks $G$ of $N$ minimize $r(G)$ if and only if it has the fewest edges among all support networks, i.e., it is a minimum support network. Therefore, an optimal solution of Problem \ref{prob:minimum reticulation} can be obtained by simply selecting an arbitrary element from $\mathcal{C}_N = \prod_{i=1}^d \mathcal{S}_{\mathcal{C}}(Z_i)$. This is done by computing the maximal zig-zag trail decomposition $\{Z_1, \dots, Z_d\}$ of $N$, and then selecting an arbitrary element of $\mathcal{S}_{\mathcal{C}}(Z_i)$ expressed in  \eqref{eq:sequence for minimum support networks} for each $Z_i$.

For example, the network $N$ in Figure~\ref{fig:zigzagtrail decomposition} is decomposed into the maximal zig-zag trails $Z_1$ through $Z_7$. According to \eqref{eq:sequence for minimum support networks}, the sequence $\langle 11 \rangle$ is $\mathcal{C}$-admissible for $E(Z_1)$, $E(Z_2)$, and $E(Z_5)$; $\langle 1010 \rangle$ is $\mathcal{C}$-admissible for $E(Z_3)$ and $E(Z_4)$; and $\langle 1 \rangle$ is $\mathcal{C}$-admissible for $E(Z_6)$ and $E(Z_7)$. Piecing these $\mathcal{C}$-admissible subsets together yields the edge-set of a support network $G^\ast$ of $N$ with the minimum reticulation number, that is, $r(G^\ast) = 1$.



\begin{theorem}
  \label{thm:linear-time.ret.min}
  The above algorithm solves Problem~\ref{prob:minimum reticulation} in $\Theta(|E(N)|)$ time.
\end{theorem}

When $N$ is tree-based, $r^\ast(N)=0$ holds and a support network $G$ with $r(G^\ast)=0$ is simply its support tree. In general, $r(G^\ast)$ equals the number of W-fences in the maximal trail decomposition of $N$. 


\section{Finding a support network with the minimum level}\label{sec:minimum.level}
In Section \ref{sec:Problem}, we have also defined $\mathrm{level}^\ast(N)$, i.e., the base level of $N$.    
In contrast to Problem~\ref{prob:minimum reticulation}, we conjecture that Problem~\ref{prob:level opt} is NP-hard. Here, we provide exact and heuristic exponential algorithms for solving Problem~\ref{prob:level opt}. 

\begin{problem}[\textsc{Level Minimization}]
  \label{prob:level opt}
%  Given a rooted binary phylogenetic network $N$, find a support network $G^\ast$ with the minimum level, and the value of $\mathrm{level}(G^\ast)=\mathrm{level}^\ast(N)$.  
    Given a rooted binary phylogenetic network $N$, compute the base level, $\mathrm{level}^\ast(N)$, and find a support network $G$ with $\mathrm{level}(G)=\mathrm{level}^\ast(N)$.
 \end{problem}



\subsection{Exact algorithm}
An obvious exact algorithm for Problem \ref{prob:level opt}  computes $\mathrm{level}(G)$ of each element $G$ in $\mathcal{A}_N$ to obtain the minimum value, but this method is clearly impractical. Algorithm \ref{alg:ExactAlgorithm} performs an exhaustive search in $\mathcal{B}_N$ instead of $\mathcal{A}_N$. Recalling the numerical results in Table \ref{tab:experiment 1}, we know that this search space reduction is significant. We can prove that $\mathcal{B}_N$ contains a correct $G^\ast$,  yielding  
 Theorem \ref{thm:alg1}. The proof  is given in Appendix. 



\begin{algorithm}
  \caption{Exact method for solving \textsc{Level Minimization} (Problem \ref{prob:level opt})}
  \label{alg:ExactAlgorithm}
  \KwIn{A rooted binary phylogenetic network $N$}
  \KwOut{A support network $G^\ast$ of $N$ with the minimum level, the value of $\mathrm{level}^\ast(N)$}
  \ForEach{$G \in \mathcal{B}_N$}{
    compute $\mathrm{level}(G)$ 
  }
  let $G^\ast$ be a support network $G$ with the minimum $\mathrm{level}(G)$ in $\mathcal{B}_N$\;
  \Return $G^\ast$, and $\mathrm{level}(G^\ast)$ as $\mathrm{level}^\ast(N)$
\end{algorithm}

\begin{theorem}\label{thm:alg1}
Algorithm \ref{alg:ExactAlgorithm} returns a correct solution of Problem \ref{prob:level opt}. It runs  in $O(|\mathcal{B}_N|\cdot |E(N)|) = O(\psi^{|E(N)|}\cdot |E(N)|)$ time, where $\psi$ is as in Theorem~\ref{thm:counting by padovan, perrin}. 
%  Let $N$ be a level-$k$-based rooted binary phylogenetic network. Then Algorithm~\ref{alg:ExactAlgorithm} correctly outputs a support network $N^\ast$ with $\mathrm{level}(N^\ast)=k$. It runs in $O(|\mathcal{B}_N|\cdot |E(N)|) = O(\psi^{|E(N)|}\cdot |E(N)|)$ time, where $\psi$ is defined in Theorem~\ref{thm:counting by padovan, perrin}. 
\end{theorem}

