%Fix a solution $\sigma = (S, X, Y)$ that satisfies the property guaranteed by \Cref{cl:fvs-longpath} for every relevant long path $\pi$. Now fix a relevant long path $\pi$, and suppose that at least one edge of $\pi$ does not exist in the resulting intersection graph $G(\cD(P, Y))$, then we know that 

\paragraph{Replacing Reducible Paths.} Now we seek to replace the internal vertices of a reducible path $\pi$ by remembering some information about how a solution can remove an edge of $\pi$. Fix a reducible path $\pi = (v_0, v_1, v_2, \ldots, v_\ell, v_{\ell+1})$, where $v_{0}$ and $v_{\ell+1}$ have degree at least $3$ in $H$. We replace $\pi$ by a special kind of an edge $e(\pi)$, which we call a \emph{reducible edge}. Note that there may be multiple reducible (short or long) paths $\pi_1, \pi_2, \ldots, \pi_t$ with common endpoints $p$ and $q$. We replace each such $\pi_i$ with an associated reducible edge $e(\pi_i)$. Furthermore, both the endpoints of a reducible path may be the same vertex $p$ with degree at least $3$, in which case we replace each such $\pi_i$ with a reducible edge $e(\pi_i)$ which is a self-loop (note that in this case the internal degree-$2$ vertices on $\pi_i$ must be at least $2$). Thus, the resulting graph may be a multigraph with multiple parallel edges between vertices of degree at least $3$, and multiple self-loops on vertices. 

Next, we annotate each reducible edge $e(\pi)$ with a tuple that encodes information about different ways in which a solution of $\Pi_1$ or $\Pi_2$ can shrink some disks in order to remove different edges of $\pi$. First, consider the case where $\pi$ is a long reducible path. Let $\dstart \coloneqq |v_0v_1|$, $\dend \coloneqq |v_\ell v_{\ell+1}|$, and $\displaystyle \dmax \coloneqq \max_{1 \le i \le \ell-1} |v_i v_{i+1}|$. For $\Pi_2$, we simply annotate $e(\pi)$ with the tuple $(\dstart, \dend, \dmax)$. For $\Pi_1$, we annotate the edge with the tuple $(\nu(\dstart), \nu(\dend), \nu(\dmax))$. 

Note that if $\pi$ is a short reducible path, then note that $\dmax$ may not be defined as per the definition above, in which case we define it to be $\bot$. For $\Pi_2$, we annotate $e(\pi)$ with $(\dstart, \dend, \dmax)$. For $\Pi_1$, we annotate $e(\pi)$ with $(\nu(\dstart), \nu(\dend), \nu(\dmax))$, where we define $\nu(\bot) \coloneqq \bot$. For each reducible edge $e$, we use the shorthand $\nu_{\sfstart}(e), \nu_\sfend(e), $ and $\nu_{\sfmax}(e)$ to denote the annotated values.

\paragraph{Annotating Remaining Edges.} Consider an edge $e = pq \in E(H)$ in the original graph such that $p$ and $q$ are distinct vertices of degree at least $3$. We say that $e$ is an \emph{original edge}. We annotate each original edge as follows. For $\Pi_2$, we simply annotate it with $|pq|$, whereas for $\Pi_1$, we annotate the edge with $\nu(|pq|)$, which we refer to as $\#(e)$.

After replacing all reducible paths with reducible edges, and annotating all original edges, we have the following observation. 
\begin{observation} \label{obs:fvs-degbound-loops}
	After replacing all reducible paths with reducible edges, the degree of every vertex is upper bounded by $25k+50$, where we assume that a self-loop incident to a vertex $v$ contributes $2$ to the degree of $v$.
\end{observation}
\begin{proof}
	Consider the operation of replacing a reducible path $\pi$ with a reducible edge $pq$. Suppose $p$ and $q$ are distinct, then the degree-$2$ vertices on $\pi$ contribute exactly one toward the degrees of $p$ and $q$ respectively. On the other hand, if $p = q$, then there are at least two degree-$2$ vertices on $\pi$, which contribute one each to the degree of $p$. Thus, the replacement operation preserves the degree of each vertex that had degree at least $3$ in the original graph $G$ in all cases. Since each vertex has degree at most $25k+50$ from \Cref{redrule:fvs1}, the observation follows.
\end{proof}

\subsection{A Polynomial Kernel for \probAcyclicityDown.} \label{subsec:polykernel-fvs}

We have an annotated multigraph $H_A$ with multiple parallel edges between pairs of vertices, and multiple self-loops on a vertex such that the degree of each vertex $v \in V(H_A)$ is at least $3$ and at most $25k+50$. Let $E_r$ denote the set of reducible edges of $E(H_A)$, and $E_o$ denote the set of original edges of $E(H_A)$. We want to decide the following problem on $H_A$, which we call $\Pi'_1$. 
\ \\\begin{tcolorbox}[colback=gray!5!white,colframe=gray!75!black]
	\begin{description}
		%\setlength{\itemsep}{-2pt}
		\item[Input:]  An annotated multigraph $H_A$ with multiple parallel edges between pairs of vertices, a total order $\prec$ on $V(H_A)$, and a parameter $k$.
		\item[Task:] Determine whether there exists a solution $\sigma_{\Pi'_1} = (W, (F, K_o, K_r), f_o, g_r, c_r, w_r)$, where
		\begin{itemize}[leftmargin=*]
			\item $W \subseteq V(H_A)$ {\footnotesize \em $\triangleright$ denotes the set of vertices of degree at least $3$ that are shrunk}
			\item $(F, K_r, K_o)$ is a partition of $E(H)$ with $K_r \subseteq E_r$, and $K_o \subseteq E_o$ \newline{\ \qquad \footnotesize \em $\triangleright$ $F$ induces a forest, and the edges of $K_r \cup K_o$ are removed}
			\item $f_o: K_o \to W \cup (W \times W)$, {\footnotesize \em $\triangleright$ $f_o$ specifies how an original edge is removed}
			\item $g_r: K_r \to \{{\sf start, end, max}\}$, $c_r: K_r \to \{1, 2\}$, $n_r: K_r \to \{0, 1\}$, and $w_r: K_r \to W$ \newline{\footnotesize \em  $\triangleright$ $g_r$ encodes how an edge is removed, $c_r$ encodes how many degree-$2$ vertices are implicitly removed, and $w_r$ encodes the endpoints of reducible path to be removed}
		\end{itemize}
		such that the following properties are satisfied:
		\begin{itemize}[leftmargin=*]
			\item The graph $(V(H_A), F)$ is simple (i.e., without self-loops or parallel edges), and acyclic,
			\item  If $e = pq \in K_o$, (i) $\emptyset \neq f_o(e) \subseteq \{p, q\}$, (ii) $f_o(e) \subseteq W$, and (iii) $|f_o(e)| = \#(e)$ \newline{\footnotesize \em $\triangleright$ an original edge can be removed by shrinking one or both of its endpoints, as specified by its annotation}
			\item If $e = pq \in K_r$, with $p \preceq q$ then at least one of $\nu_{\sfstart}, \nu_{\sfend}$, and $\nu_{\sfmax}$ is at least $1$, and:
			\begin{itemize}[leftmargin=*]
				\item If $g_r(e) = {\sf start}$, then $\nu_{\sfstart}(e) \ge 1$, and $w_r(e) = p$. 
				\newline If $\nu_{\sfstart}(e) = 2$, then $c_r = 1$ 
				\newline{\footnotesize \em $\triangleright$ If a $e$ is removed by removing the first edge on the reducible path, then only shrink $p$ if possible}
				\item If $g_r(e) = {\sf end}$, then $\nu_{\sfend}(e) \ge 1$, and $w_r(e) = q$. 
				\newline If $\nu_{\sfend}(e) = 2$, then $c_r = 1$
				\item If $g_r(e) = {\sf max}$, then $c_r(e) = \nu_{\sfmax}(e) \ge 1$.
			\end{itemize}
			\item $\displaystyle |W| + \sum_{e \in K_r} c_r(e) \le k$
		\end{itemize}
	\end{description}
\end{tcolorbox}

\begin{lemma} \label{lem:fvs-pi1-compression-bound}
	If $(H_A, \prec, k)$ is a yes-instance of $\Pi'_1$, then $|V(H_A)| = \Oh(k^2)$, and $|E(H_A)| = \Oh(k^3)$, accounting for multiplicities.
\end{lemma}
\begin{proof}
	If $(H_A, \prec, k)$ is a yes-instance of $\Pi'_1$, then there exists a solution $\sigma = (W, (F, K_o, K_r), f_o, g_r, c_r, w_r)$ with the specified properties. Let $K_r' \subseteq K_r$ be the set of edges with $g_r(e) = \sfmax$, i.e., the edges that are removed by the virtue of deletion of internal vertices. Let $K' = (K_o \cup (K_r \setminus K'_r)$, denote the remaining set of edges that are removed. We observe that for any edge $e \in K'$, at least one endpoint of $e$ belongs to the set $W$. Since $(V(H_A), F)$ is a forest, $W$ is a \emph{feedback vertex set} (in the normal sense) for the graph $H'_A = (V(H_A), F \cup K')$.

	Recall that in the graph $H_A$, the minimum degree is at least $3$. However, in graph $H'_A$, at most $2k$ vertices may have degree at most $2$, by the virtue of removal of the edges of $K'_r$. This follows from the fact that each edge $e \in K'_r$ has $c_r(e) \ge 1$, and $\sum_{e \in K'_r} c_r \le \sum_{e \in K_r} c_r \le k$. In the following, we use a slight variation of the argument that bounds the number of vertices in a graph with minimum degree $3$ and maximum degree $\Delta$, and feedback vertex set of size $k$.

	Let $m \coloneqq |V(H_A)| = |V(H'_A)|$, and let $E_W \subseteq F \cup K'$ denote the set of edges with at least one edge incident to a vertex of $W$. Note that $|E_W| \le \Delta |W|$. Finally, let $Q \coloneqq V(H) \setminus W$. Note that $H'_A[Q]$ is a forest, which implies that the number of edges in $H'_A[Q]$ is at most $|Q|-1$.  It follows that
	\begin{align*}
		\Delta |W| \ge |E_W| &\ge |E(H'_A)| - (m-|W| -1) 
		\\&\ge \frac{3(m-2k)}{2} - (m - |W| -1) \tag{Since all except at most $2k$ vertices of $H'_A$ have degree at least $3$ in $H'_A$}
		\\\implies (\Delta-1) \cdot |W| &\ge \frac{m}{2} - 3k + 1
		\\\implies k \ge |W| &\ge \frac{m/2 - 3k+1}{(\Delta-1)}
	\end{align*}
	It follows that $m \le k \cdot (\Delta-1) + 3k - 1$, which is upper bounded by $\Oh(k^2)$, since $\Delta = \Oh(k)$. Since each vertex of $V(H_A)$ has degree at most $\Oh(k)$, it follows that the number of edges in $H$ (accounting for multiplicities) is $\Oh(k^3)$.
\end{proof}

\begin{lemma} \label{lem:fvs-pi1-equivalence}
	The original instance $\cI$ of $\Pi_1$ is a yes-instance iff the instance $(H_A, \prec, k)$ of $\Pi'_1$ as defined above is a yes-instance.
\end{lemma}
\begin{proof}
	It suffices to focus on the instance $\cI$ obtained after repeatedly applying reduction rules \Cref{redrule:fvs0}, \Cref{redrule:fvs1}, \Cref{redrule:fvs2}, \Cref{redrule:fvs3}, \Cref{redrule:fvs-4-isolated-cycles}. Consider a solution $\sigma = (S, X, Y)$ to $\Pi_1$ that shrinks at most $2$ disks corresponding to internal vertices on any reducible path, in accordance with \Cref{cl:fvs-longpath}. 

	\textbf{Forward direction.} We obtain a solution for the instance $(H, \prec, k)$ of $\Pi'_1$.	Let $W = V(H) \cap S$.
	If an original edge $pq$ is removed by $\sigma$ such that $p$ and $q$ have degree at least $3$ in $H$, then we add $pq$ to $K_o$, and define $f_o(e) = \{p, q\} \cap S$. Furthermore, from \Cref{obs:nu-properties}, $e$ can be removed by shrinking exactly $\nu(|pq|) = \#(e)$ endpoints. Note that $\#(e)$ also contributes toward $|W|$.

	Now fix a reducible path $\pi$ with endpoints $v_0 = p$ and $v_{\ell + 1} = q$ (with $v_0 \preceq v_{\ell+1}$) such that $\sigma$ removes at least one edge of $\pi$. Then, we add $e(\pi)$ to $K_r$. We consider different cases.
	\begin{itemize}
		\item If $\sigma$ removes the edge $e = v_0v_1$. We define $g_r(e) = \sfstart$. Via \Cref{obs:nu-properties}, if $\nu(|v_0v_1|) = \nu_{\sfstart} = 1$, then we can wlog assume that it shrinks $v_0$ (since it may also potentially eliminate other edges incident to $v_0$; whereas shrinking $v_1$ only affects $\pi$). Then, we set $w_r(e) = \{v_0\}$. 
		\\If $\nu(|v_0v_1|) = \nu(\sfstart) = 2$, then $\sigma$ must shrink both $v_0$ as well as $v_1$. In this case, we set $w_r(e) = \{v_0\}$, and $c_r = 1$. Note that we account $v_1$ in the form of $c_r(e)$ in the objective function.
		\item The case where $\sigma$ removes the edge $e = v_\ell v_{\ell+1}$ is symmetric to the previous case, and thus we omit it.
		\item If $\sigma$ removes an edge $e = v_i v_{i+1}$, where both $v_i$ and $v_{i+1}$ are internal degree-$2$ vertices of $\pi$. Without loss of generality, we can assume that $e = v_i v_{i+1}$ realizes the maximum distance $\dmax = \min_{1 \le j \le \ell-1} |v_j v_{j+1}|$. We set the value of $c_r(e)$ as $\nu_{\sfmax}$, since \Cref{obs:nu-properties} implies that $e$ can be removed by shrinking exactly $\nu_{\sfmax}$ disks.
	\end{itemize}
	We note that the subgraph induced by (i) edges of reducible paths $\pi$ such that no edge of $\pi$ is removed by $\sigma$, and (ii) original edges that are not removed by $\sigma$, induce a forest in the resulting graph $G(P, r)$. We let $F$ to be the set of corresponding reducible and original edges, which implies the graph $(V(H_A), F)$ is simple, and acyclic.	It is not difficult to verify that every disk that is shrunk by $\sigma$ contributes exactly $1$ to the objective of $\Pi'_1$. 

	\textbf{Backward direction.} Suppose $(H_A, \prec, k)$ is a yes-instance of $\Pi'_1$, and consider a solution $\sigma' = (W, (F, K_o, K_r), f_o, g_r, c_r, w_r)$ to $(H, \prec, k)$. We retrieve a solution $\sigma$ to the instance $\cI$ of $\Pi_1$. For every edge $e = pq \in K_o$, we shrink one or both of its endpoints, as specified by $f_o(e)$. For an edge $e = pq \in K_r$ with $p \preceq q$ corresponding to a reducible path $\pi = (p = v_0, v_1, \ldots, v_\ell, v_{\ell+1} = q)$, we consider the following different cases.
	\begin{itemize}
		\item If $g_r(e) = \sfstart$, and $\nu_{\sfstart} = 1$, then we shrink $p$ in the solution $\sigma$. If $\nu_{\sfstart} = 2$, then we shrink both $p$ and $v_1$ in $\sigma$.
		\item The case when $g_r(e) = \sfend$ is analogous to the previous case.
		\item If $g_r(e) = \sfmax$, then we shrink one or both endpoints of the edge $v_i v_{i+1}$ realizing the maximum euclidean distance along $\pi$, as specified by $c_r(e)$.  
	\end{itemize}
	Note that we can subdivide each reducible edge in $H$ appropriate number of times to obtain the original intersection graph $H$. However, the graph $(V(H_A), F)$ is a forest, and each edge of $F$ corresponds to an original edge, or a reducible path for which no edge is removed by $\sigma$. Furthermore, for every other reducible path $\pi$, $\sigma$ removes \emph{at least} one edge of $\pi$, disconnecting $\pi$. Therefore, the resulting intersection graph $G(P, r)$ corresponding to $\sigma$ is acyclic. Finally, it is not difficult to verify that the number of disks shrunk by $\sigma$ is at most $k$.
\end{proof}

The following observation is easy to verify, since a verification algorithm simply checks whether all the conditions in the definition of $\Pi_1$ are satisfied. 
\begin{observation} \label{obs:fvs-pi1-np}
	The problem $\Pi'_1$ is in \classNP.
\end{observation}

%\begin{theorem} \label{thm:fvs-polykernel}
%	There exists a polynomial kernel for \probAcyclicityDown parameterized by the number of disks $k$ that one is allowed to shrink.
%\end{theorem}
\fvspolykernel*
\begin{proof}
	Given an instance $\cI$ of \probAcyclicityDown, we obtain an equivalent instance $(H_A, \prec, k)$ of $\Pi'_1$ using \Cref{lem:fvs-pi1-equivalence}. Using \Cref{lem:fvs-pi1-compression-bound}, either (i) $|V(H_A)| = \Oh(k^2)$ and $|E(H_A)| = \Oh(k^3)$ -- otherwise we can conclude that $\cI$ is a no-instance. If at any point we conclude that $\cI$ is a no-instance, then we simply output a trivial no-instance of $\Pi_1$.

	Now assume that the number of vertices and edges in the instance $(H_A, \prec, k)$ is bounded. Furthermore, each edge is annotated with $\Oh(1)$ bits of information. \Cref{obs:fvs-pi1-np} implies that $\Pi'_1$ is in \classNP; whereas \Cref{thm:np-hardness-fvs} implies that \probAcyclicityDown is \classNPC. Therefore, there exists a polynomial-time reduction from the instance $(H, k)$ of $\Pi'_1$ that outputs an equivalent instance $\cI'$ of \probAcyclicityDown. Note that the size of the instance, and the parameter in the new instance $\cI'$ can be bounded by a polynomial in $k$. This implies the existence of a polynomial kernel for \probAcyclicityDown.
\end{proof}

\subsection{An FPT algorithm for \probAcyclicityMinDown via Partial Compression} We proceed as in \Cref{subsec:annotated} and summarize the situation after (i) replacing all isolated cycle components with isolated cycle vertices, (ii) replacing all reducible paths with reducible edges, and (iii) annotating all isolated cycle vertices, and all the edges (reducible as well original). We have an annotated multigraph $H_A$ with multiple parallel edges between vertices, and multiple self-loops on vertices. Note that $V(H_A) = V_b \uplus V_c$, where all vertices in $V_b$ have degree at least $3$, whereas all vertices in $V_c$ are isolated cycle vertices. Similarly, $E(H_A) = E_r \uplus E_o$, where $E_r$ and $E_o$ denote the sets of reducible and original edges respectively.
\begin{itemize}
	\item Each $e(\pi) = pq \in E_r$ with $p \preceq q$ corresponding to an reducible path $\pi$ is annotated with a tuple $(\dstart, \dend, \dmax)$. We refer to these values by $\dstart(e), \dend(e)$, and $\dmax(e)$ respectively.
	\item For each isolated cycle vertex $v(C)$ is annotated with $\#(v(C))$ and $\cost(v(C))$.
	\item Each $e = pq \in E_o$ is annotated with $d(e) = |pq|$.
\end{itemize}
Now we define the following annotated problem $\Pi'_2$, and prove that this is equivalent to $\Pi_2$.
\ \\\begin{tcolorbox}[breakable,colback=gray!5!white,colframe=gray!75!black]
	\begin{description}[]
		\item[Input:] An annotated multigraph $H_A$ with (possibly) multiple parallel edges between pairs of vertices, a total order $\prec$ on $V(H_A)$, a parameter $k$, and budget $\mu$.
		\item[Task:] Determine whether there exists a solution $\sigma_{\Pi'_2} = (W, (F, K_o, K_r), f_o, g_r, c_r, w_r, y_w, y_r)$, where 
		\begin{itemize}[leftmargin=3pt]
			\item $W \subseteq V(H_A)$ {\footnotesize \em $\triangleright$ denotes the set of vertices of degree at least $3$ that are shrunk}
			\item $(F, K_r, K_o)$ is a partition of $E(H_A)$ with $K_r \subseteq E_r$, and $K_o \subseteq E_o$ \newline{\ \qquad \footnotesize \em $\triangleright$ $F$ induces a forest, and the edges of $K_r \cup K_o$ are removed}
			\item $f_o: K_o \to W \cup (W \times W)$, {\footnotesize \em $\triangleright$ $f_o$ specifies how an original edge is removed}
			\item $g_r: K_r \to \{{\sf start, end, max}\}$, $c_r: K_r \to \{1, 2\}$, $n_r: K_r \to \{0, 1\}$, and $w_r: K_r \to W$ \newline{\footnotesize \em  $\triangleright$ $g_r$ encodes how an edge is removed, $c_r$ encodes how many degree-$2$ vertices are implicitly removed, and $w_r$ encodes the endpoints of reducible path to be removed}
			\item $\tilde{r}: V(H) \to [0, 1]$, and $y_e: E_r \to [0, 2]$ \newline{\footnotesize \em  $\triangleright$ $\tilde{r}$ encodes the new radius of a vertex in $V(H_A)$, and $y_e$ encodes the cost contributed by implicit shrinking of degree-$2$ vertex that helps in removal of an edge}
		\end{itemize}
		such that the following properties are satisfied.
		\begin{itemize}[leftmargin=3pt]
			\item The graph $(V(H_A), F)$ is simple (i.e., without self-loops or parallel edges), and acyclic,
			\item $\tilde{r}(p) <1$ iff $p \in W$; and for all remaining $q \in V(H) \setminus W$, $\tilde{r}(q) = 1$.
			\\$y_e(e) > 0$ iff $e \in K_r$; otherwise $y_e(e) = 0$ for $e \in E_r \setminus K_r$.
			\item  If $e = pq \in K_o$, then $d(e) \ge 2\alpha$, and \newline
			(i) $\emptyset \neq f_o(e) \subseteq \{p, q\}$, (ii) $f_o(e) \subseteq W$, and (iii) $\tilde{r}(p) + \tilde{r}(q) \le d(e)$ \\{\footnotesize \em $\triangleright$ at least one of the endpoints must be shrunk as specified by the annotation}
			%\newline{\footnotesize \em $\triangleright$ an original edge can be removed by shrinking one or both of its endpoints, as specified by its annotation}
			\item Suppose $e = pq \in K_r$, with $p \preceq q$, and $g_r(e) = \sfstart$.
