			\newline (B) If $1+\alpha \le \dstart(e) \le 2$, then 
			\newline\hspace*{20mm} (i) $\tilde{r}(p) \ge 2-\dstart(e)$.
			\item Suppose $e = pq \in K_r$, with $p \preceq q$, and $g_r(e) = \sfend$.
			\\Then $\dend(e) \ge 2\alpha$, $w_r(e) = q$ with $q \in W$, and
			\newline (A) If $2\alpha < \dend(e) < 1+\alpha$, then 
			\newline\hspace*{20mm} (i) $\tilde{r}(q) = \alpha$, (ii) $y_e(e) \ge \dstart(e)-\alpha$, (iii) $c_r(e) = 1$
			\newline (B) If $1 \le \dend(e) \le 2$, then 
