Observe that expanding $k$ disks of radius $1$ to radius $\beta$  is equivalent to shrinking  $|P|-k$ disks of radius $\beta$ to radius $1$. Thus, \probConnectivityFracDown and  \probConnectivityFracUp are indeed dual.

\probConnectivityFracUp is trivial if $\beta=1$. We show that the problem is \classNP-hard for every $\beta>1$.


\begin{theorem}\label{thm:hard-one}
	For every rational $\beta>1$, \probConnectivityFracUp  is  \classNP-hard. Furthermore, for any $\beta\geq 2$, the problem is \classNP-hard when restricted to the sets of points with integer coordinates. 
\end{theorem}

\begin{proof}
	We reduce from \textsc{Monotone Planar $3$-SAT} with instances satisfying (a)--(c). Consider such an instance $\varphi$ with variables $v_1,\ldots,v_n$ and clauses $C_1,\ldots,C_m$. Let $\ell$ be be the maximum number of occurrences of a variable in the clauses. Let also 
	$\delta>0$ be a rational constant and let
	$s=2\delta n(\ell+1)$, $q=2(\lceil \delta/2\rceil+1)$ and $d=q+6$. 
	For the proof for $\beta<2$, we take $\delta=\beta-1$ and for the case $\beta\geq 2$, we set $\delta=\lfloor \beta\rfloor-1$. 


	\begin{sidewaysfigure}[p]
		\centering
		\scalebox{0.75}{
			\input{Variable-Up.pdf_t}
		}
		\caption{The variable gadget for $v_i$. The radius scaling corresponding to the positive assignment of $v_i$ is shown by dashed blue circles.}\label{fig:var-one}
	\end{sidewaysfigure}

	For each variable $v_i$, we construct the set of points as it is shown in Figure~\ref{fig:var-one}. Since we are constructing an instance of \probConnectivityFracUp, we draw disks of radius one having their centers in the points instead of points themselves to show the connectivity.  Denote $P_i$ the set of points in the gadget. The points $y_{ij},\overline{y}_{ij},y'_{ij},\overline{y}'_{ij}$ are used to connected the variable gadget with the gadgets that will be constructed for clauses. The crucial idea behind the construction of the gadget is that if we are forced to set $r(p)=\beta$ to at most $2\ell+2$ points $p$ in the gadget then (a)~we have to set $r(p)=\beta$ for exactly $2\ell+2$ points, 
	(b)~because of the points $z_i,z'_{i}$ and $z_{ij},z'_{ij}$ for $j\in\{1,\ell\}$, for each of these $z$-points, we have to assign $r(p)=\beta$ to one of closest the $y$-points $p$, and moreover (c)~the assignment for $y$-points has to be ``synchronized'' as it is shown in   Figure~\ref{fig:var-one}. Thus, we obtain exactly two possible choices for the assignment corresponding to the value of the variable $v_i$.



	Recall that $G_\varphi$ has a special planar embedding demonstrated in Figure~\ref{fig:sat}. We use this and construct the set of points $P$ as it is shown in Figure~\ref{fig:clause-one}:
	\begin{itemize}
		\item arrange variable gadgets for $v_1,\ldots,v_n$ along a line at distances two and construct $m-1$  ``connecting'' greenpoints $b_1,\ldots,b_{m-1}$ between them,
		\item for each $k\in\{1,\ldots,m\}$, construct a set of points $S_k$ (shown in magenta) corresponding to the clause $C_k$ in such a way that the unit disk graph with disks having their centers in $S_k$ form a  ``three-legged'' structure; the structures for distinct clauses should be non-intersecting. 
	\end{itemize}
	We set $N=|P|$ and define $k=2n(\ell+1)$. This completes the construction of the instance $(P,k,\beta)$ of \probConnectivityFracUp.
	Since $\delta$ is rational, we have that the points of $P$ have rational coordinates, and if $\delta$ is integer, then 
	the coordinates of the points can be chosen to be integer.
	By~\cite{KnuthR92}, it can be seen that the construction of $(P,k,\beta)$ from $\varphi$
	can be done in polynomial time.

	\begin{sidewaysfigure}[p]
		\centering
		\scalebox{0.75}{
			\input{Clause-Up.pdf_t}
		}
		\caption{The connection of  the variable gadgets and the construction of the clause gadgets; here $C_r=v_h\vee v_i\vee v_j$ and 
			$C_r=\overline{v}_h\vee \overline{v}_i\vee \overline{v}_j$.
			The radius epansion corresponding to the positive assignment of $v_h$ and the negative assignment of $v_i$ is shown by dashed blue circles.}\label{fig:clause-one}
	\end{sidewaysfigure}

	We claim that the Boolean variables $v_1,\ldots,v_n$ have an assignment satisfying $\varphi$ if and only if  $(P,k,\beta)$ is a yes-instance of \probConnectivityFracUp.

	First, we assume that $\varphi$ is satisfied by an assignment of $v_1,\ldots,v_n$. For each $i\in\{1,\ldots,n\}$, we set 
	$S_i=\{y_i, y_{i'}\}\cup\{y_{ij},y_{ij}'\mid j\in\{1,\ldots,\ell\}\}$ if $v_i=true$. Symmetrically, we set 
	$S_i=\{\overline{y}_i, \overline{y}_i'\}\cup\{\overline{y}_{ij},\overline{y}_{ij}\mid j\in\{1,\ldots,\ell\}\}$ if $v_i=false$ (see Figure~\ref{fig:var-one}). Then we define $S=\bigcup_{i=1}^nS_i$ and 
	define the function $r\colon P\rightarrow \{1,\beta\}$ by setting 
	$r(p)=\beta$ for $p\in S$ and $r(p)=1$ for the other points $p$. Notice that $|S|=2n(\ell+1)=k$. % we set $r(p)=\beta$ for exactly $2n(\ell+1)=k$ points. 

	For each $i\in\{1,\ldots,n\}$, we have that the disk graph $G(P_i,r_i)$, where  $r_i$ is the restriction of $r$ on $P_i$,
	is connected (see Figure~\ref{fig:var-one}). Due to the disks of radius one with centers in the points in $b_1,\ldots,b_m$, the subgraphs $G(P_i,r_i)$ are connected with each other in $G(P,r)$.
	For each $k\in \{1,\ldots,m\}$, $G(S_k,r_k')$, where $r_k'$ is the restriction of $r$ on $S_k$,  is connected (see Figure~\ref{fig:clause-one}). Moreover, because $\varphi$ is satisfied, we have that if $C_k=v_h\vee v_i\vee v_j$, then one of the graphs  $G(P_h,r_h)$, $G(P_i,r_i)$, $G(P_j,r_j)$ has a disks intersecting a disk of  $G(S_k,r_k')$. For clauses with negative literals, the arguments are the same. This implies that  $G(P,r)$ is connected. 

	For the opposite direction, assume that $S\subseteq P$ is a set of point of size at most $k$ such that $G(P,r)$ is connected for 
	$r(p)=
	\begin{cases}
		\beta&\mbox{if } p\in S,\\
		1&\mbox{if } p\in P\setminus S.
	\end{cases}
	$

	For each $i\in\{1,\ldots,n\}$, let 
	$Z_i=\{z_i,z_i',z_{i1},\ldots,z_{i\ell},\overline{z}_{i1},\ldots,\overline{z}_{i\ell}\}$ (see Figure~\ref{fig:var-one}; these points are shown in red), and let $Z=\bigcup_{i=1}^nZ_i$. 
	Because the disk graph $G(P,r)$ is connected, for every $z\in Z$, there is a point $p\in P$ distinct from $z$ such that $r(z)+r(p)\leq 1+\beta$, that is, either $z\in S$ or $p\in S$.
	We say that $p$ is \emph{assigned} to $z$ if $p\in S$ and $r(p)=\beta$. By the choice of $\delta$ and $q$, no point $p$ can be assigned to two distinct $z,z'\in Z$. Because $|Z_i|=2(\ell+1)$ for every $i\in\{1,\ldots,n\}$, we have that $|Z|=2n(\ell+1)=k$. We obtain that (a) for every $z\in Z$, at most one point $p_z\in P$ is assigned to $z$ and (b) for every $p\in P\setminus Z$ that is not assigned to any point of $Z$, $r(p)=1$.  Also by the choice of $\delta$ and $q$, we  have that for  every $i\in\{1,\ldots,n\}$, $p_{z_i}\in\{y_i,\overline{y}_i\}$, $p_{z_i'}\in\{y_i',\overline{y}_i'\}$, and $p_{z_{ij}}\in\{y_{ij},\overline{y}_{ij}\}$, $p_{z_{ij}'}\in\{y_{ij}',\overline{y}_{ij}'\}$ for $j\in\{1,\ldots,\ell\}$ (see Figure~\ref{fig:var-one}). 


	Consider $i\in\{1,\ldots,n\}$. Suppose that either no point is assigned to $z_i$ or $p_{z_i}=y_i$. Then consider the points from the set $A_{i0}$ (again, we refer to Figure~\ref{fig:var-one}). Since $r(p)=1$ for $p\in A_{0i}$, we have that $p_{z_{i1}}=y_{i1}$ to ensure the connectivity. By the same arguments for $A_{i1}$, $p_{z_{i2}}=y_{i2}$. Iterating, we obtain that $r(y_i)=r(y_i')=r(y_{i1})=\ldots=r(y_{i\ell})=r(y_{i1}')=\ldots=r(y_{i\ell}')=\beta$ and 
	$r(\overline{y}_i)=r(\overline{y}_i')=r(\overline{y}_{i1})=\ldots=r(\overline{y}_{i\ell})=r(\overline{y}_{i1}')=\ldots=r(\overline{y}_{i\ell}')=1$. 
	If this holds, we set the value of the Boolean variable $v_i=true$. Symmetrically, if $p_{z_i}=\overline{y}_i$, then 
	$r(y_i)=r(y_i')=r(y_{i1})=\ldots=r(y_{i\ell})=r(y_{i1}')=\ldots=r(y_{i\ell}')=1$ and 
	$r(\overline{y}_i)=r(\overline{y}_i')=r(\overline{y}_{i1})=\ldots=r(\overline{y}_{i\ell})=r(\overline{y}_{i1}')=\ldots=r(\overline{y}_{i\ell}')=\beta$, and we set $v_i=false$ in this case. 
	We claim that this is a satisfying assignment for $\varphi$.   

	To see the claim, consider $C_k$ for some $k\in\{1,\ldots,m\}$. By symmetry, we can assume that $C_k=v_h\vee v_i\vee v_j$, that is, the clause contains only positive literals. Observe that the set of points $S_k$ corresponding to $C_k$ (see Figure~\ref{fig:clause-one}) contains exactly tree points that are at distance $2\alpha+\delta$ from $y_{hh'}$, $y_{ii'}$, and $y_{jj'}$, respectively, for some $h',i',j'\in\{1,\ldots,\ell\}$, and other points of $S_k$ are at distances that are bigger than $\beta+1$ from the points of the variable gadgets. Then because $G(P,r)$ is connected,
	$r(y_{hh'})=\beta$ or $r(y_{ii'})=\beta$ or $r(y_{jj'})=\beta$. This means that at least one of the variables $x_h$, $x_i$, $x_j$ is set $true$. This proves that $C_k$ is satisfied. 
	As $k\in\{1,\ldots,m\}$ is arbitrary, we obtain that $\varphi$ is satisfied. This completes the proof.
\end{proof}

