%\]


%\[
%PPPAL_i=\{wy \mid w \in XPPAL_i, m=\text{segl}(w), y\in XPAD_{m-1}\}
%\]

\[
PPPAL_i=\{w(\mathtt{a}^m0^{c_i})^{2^m-m^{i-1}-1}\mathtt{a}^m p_{i,m-1} \mid w \in PPAL_i, m=\text{segl}(w)\}
\]


The  definitions presented above correspond to extending some string $w\in PPAL_i$ stage by stage, concatenating a new substring to the right at each stage, as follows:
\begin{itemize}
    \item Append the substring $(\mathtt{a}^m0^{c_i})^{2^m-m^{i-1}-1}\mathtt{a}^m$
    \item[] \{After this stage, the extended string consists of $2^m$ segments of length $m$. Of these, the first $m^{i-1}$ are of the form $\Sigma_{\mathtt{ab}}^m$, and the remaining $2^m-m^{i-1}$ are of the form $\mathtt{a}^m$. Each neighboring pair of  newly added segments are separated by the delimiter substring $0^{c_i}$.\}
    \item For each integer $l$ from $m-1$ down to and including 1, append the substring $\$\mathtt{a}^{l}(0^{c_i}\mathtt{a}^l)^{2^l-1}$
    \item[] \{Each iteration of this loop appends a (shorter) \textit{block} consisting of $2^l$ $\mathtt{a}$-segments of length $l$. Neighboring $\mathtt{a}$-segments of equal length are separated by the delimiter substring $0^{c_i}$, whereas neighboring $\mathtt{a}$-segments of different lengths are separated by the symbol $\$$ throughout the resulting string.\}
\end{itemize}

For any $i>0$, the corresponding \textit{padded punctuated palindromes language} $PPPAL_i$ is the set of strings obtained by applying the padding procedure described above to every member of the corresponding punctuated palindromes language $PPAL_i$.

Let us  examine the common pattern %(to be named ?!?!??!??!?$\mathbf{P}$) 
imposed by our padding procedure on the resulting strings.  Employing the terminology introduced above, we see that each string $w$ in $PPPAL_i$ consists of $m$ blocks, where $m=\text{segl}(w)$. Neighboring blocks are separated by $\$$ symbols. Within each block, there are multiple segments of 
equal length, separated by binary delimiter substrings. The rightmost block contains two segments of length 1. Every other block contains twice as many segments as the block  to its right, and the length of its segments  is one more than the corresponding length in the  block to its right. 


\begin{lemma}\label{logn}
  For any $i,n>0$, if $m$ is the length of the leftmost segment of a string $s\in PPPAL_i$ such that $|s|=n$, then $m<\log n$, and there exists a positive constant $d_i$  such that $m > d_i \log n$.  
\end{lemma}
\begin{proof}
It is easy to prove by induction that any $m$-block string in $PPPAL_i$  contains $2^{m+1}-2$ segments. The total number of ``separators'' between segments is therefore $2^{m+1}-3$. Of these, $m-1$ are the $\$$ symbols which separate neighboring blocks, so there are $2^{m+1}-m-2$ binary delimiter substrings. For any fixed $i$, the total number of symbols occurring in the separators is therefore $c_i(2^{m+1}-m-2)+m-1$. It remains to consider the combined length of the segments. This is  $\sum_{l=1}^{m} l 2^l$, which is seen by another simple induction to equal
$(m-1)2^{m+1}+ 2$. So for any string of length $n$ matching  this  pattern, and having  $m$ symbols in its leftmost segment, 
\begin{equation}
    n=(m-1)2^{m+1}+c_i(2^{m+1}-m-2)+m+1. \label{eq:mlogn}
\end{equation}
This lets one conclude that  %$m\in\Theta(\log n)$ and 
$m<\log n$, and that there exists a positive constant $d_i$  such that $m > d_i \log n$.
\end{proof}




Note that the  analysis in the proof of Lemma \ref{logn} uses only the numbers, lengths and ordering of the segments and separators in the extended string, and is valid for any string matching this general pattern, even if it has no prefix that is a member of some $PPAL_i$. Just as in Theorem \ref{thm:mrpal}, the following result  will be based on the fact that the dominant term of the expected runtime of an optimal small-space QTM recognizing $PPPAL_i$ is the one associated with the task of determining whether the relevant prefix of the input contains a palindrome, and a 2QCFA can quickly check all other syntactic requirements associated with membership of $PPPAL_i$  with a very small probability of error.

\begin{theorem}\label{thm:pppal}
        For all $i\geq1$, $PPPAL_i \in \mathsf{BQTISP}(2^{O((\log n)^i)},O(1))$.
\end{theorem}
\begin{proof}

