\title{\textbf{MatMMFuse: Multi-Modal Fusion Model for Material Property Prediction}}

\author[1]{Abhiroop Bhattacharya}
\author[1]{Sylvain G. Cloutier}

\affil[1]{Department of Electrical Engineering, École de technologie supérieure, Montréal, Canada}
