\subsection{Pseudocode for implementing proposed framework}

MatMMFuse can be implemented using the following pseudocode.
\begin{algorithm}
\caption{Fusion of Graph and Text Embeddings for Material Property Prediction}
\begin{algorithmic}[1]
\Require CIF file $\mathcal{C}$, Text Description $\mathcal{T}$, Property Label $y$, Pretrained GNN $\mathcal{G}$, Pretrained Transformer $\mathcal{B}$, Attention Combiner $\mathcal{A}$, Learning Rate $\eta$, Cosine Warmup $\lambda$
\Ensure Trained Model for Property Prediction

\State \textbf{Initialize} model parameters $\theta$
\State \textbf{Split} dataset into Train $(\mathcal{D}_{train})$, Validation $(\mathcal{D}_{val})$, and Test $(\mathcal{D}_{test})$

\For{each epoch in $1, \dots, N_{epochs}$}
    \For{each batch $(\mathcal{C}_i, \mathcal{T}_i, y_i)$ in $\mathcal{D}_{train}$}
        \State \textbf{Extract Graph Features:}
        \State \quad Construct crystal graph $G_i$ from CIF file $\mathcal{C}_i$
        \State \quad Compute graph embedding: $h_G = \mathcal{G}(G_i)$
        \State \quad Project embedding: $\tilde{h}_G = W_G h_G$

        \State \textbf{Extract Text Features:}
        \State \quad Tokenize text: $X_T = \text{Tokenizer}(\mathcal{T}_i)$
        \State \quad Compute transformer embedding: $h_T = \mathcal{B}(X_T)$
        \State \quad Pool embedding: $h_T = \text{Mean}(h_T)$
        \State \quad Project embedding: $\tilde{h}_T = W_T h_T$

        \State \textbf{Fuse Representations using Attention:}
        \State \quad Compute query: $Q = W_Q \tilde{h}_T$
        \State \quad Compute key: $K = W_K \tilde{h}_G$
        \State \quad Compute value: $V = W_V \tilde{h}_G$
        \State \quad Compute attention scores: $\alpha = \text{softmax} \left( \frac{QK^T}{\sqrt{d_k}} \right)$
        \State \quad Compute attended representation: $h_{fused} = \alpha V$
        \State \quad Apply residual connection: $h_{fused} = \text{LayerNorm}(h_{fused} + \tilde{h}_T)$

        \State \textbf{Predict Property:}
        \State \quad $y_{\text{pred}} = \sigma(W_o h_{fused})$

        \State \textbf{Compute Loss:}
        \State \quad $\mathcal{L} = \frac{1}{N} \sum_{i=1}^{N} (y_i - y_{\text{pred}})^2$

        \State \textbf{Optimize Parameters:}
        \State \quad Compute gradients: $\nabla_{\theta} \mathcal{L}$
        \State \quad Update parameters: $\theta \gets \theta - \eta \cdot \lambda(t) \cdot \nabla_{\theta} \mathcal{L}$

    \EndFor
    \State Evaluate on $\mathcal{D}_{val}$ and adjust learning rate $\eta$
\EndFor

\State \textbf{Test Model:} Evaluate on $\mathcal{D}_{test}$

\end{algorithmic}
\end{algorithm}

