\subsubsection{Differential-Algebraic Equations (DAEs)}
\texttt{Differential equations:}
\begin{flalign}
        \dot{\tilde{p}} &\ =\ -\omega_{pc} (\tilde{p} - p) \label{eqn:sl11}
        \\
        \dot{\tilde{q}} &\ =\ -\omega_{qc} (\tilde{q} - q) \label{eqn:sl12}
        \\
        \dot{\gamma_\text{PLL}} &\ =\ v_\text{c,q} \label{eqn:sl7}
        \\
        \dot{\theta_\text{PLL}} &\ =\ \omega_\text{b} \Delta \omega \label{eqn:sl8}
        \\
        \dot{\phi}_\text{d} &\ =\ p^{*} - \tilde{p} \label{eqn:sl9}
        \\
        \dot{\phi}_\text{q} &\ =\ q^{*} - \tilde{q} \label{eqn:sl10}
        \\
        \dot{\gamma_\text{d}} &\ =\ i^{*}_\text{t,d} - i_\text{t,d} \label{eqn:sl3}
        \\
        \dot{\gamma_\text{q}} &\ =\ i^{*}_\text{t,q} - i_\text{t,q} \label{eqn:sl4}
        \\
        \dot{v}_\text{c,d} &\ =\ \omega_\text{b} \omega v_\text{c,q} + \frac{\omega_\text{b}}{C_\text{f}}(i_\text{t,d} - i_\text{g,d}) \label{eqn:sl5}
        \\
        \dot{v}_\text{c,q} &\ =\ -\omega_\text{b} \omega v_\text{c,d} + \frac{\omega_\text{b}}{C_\text{f}}(i_\text{t,q} - i_\text{g,q}) \label{eqn:sl6}
        \\
        \dot{i_\text{t,d}} &\ =\ \omega_\text{b} \omega i_\text{t,q} + \frac{\omega_\text{b}}{L_\text{f}}(v_\text{t,d} - v_\text{c,d}) - \frac{R_\text{f}}{L_\text{f}}\omega_\text{b} i_\text{t,d}
        \label{eqn:sl1} &&
        \\
        \dot{i_\text{t,q}} &\ =\ - \omega_\text{b} \omega i_\text{t,d} + \frac{\omega_\text{b}}{L_\text{f}}(v_\text{t,q} - v_\text{c,q})  - \frac{R_\text{f}}{L_\text{f}}\omega_\text{b} i_\text{t,q}
        \label{eqn:sl2}
\end{flalign}
\noindent 
\texttt{Algebraic equations:}
\begin{align}
    &\ \omega - \omega_0 - \Delta \omega = 0 \label{eqn:al9}
    \\&\
    \Delta \omega - K^\text{P}_\text{PLL}v_\text{c,q} - K^\text{I}_\text{PLL}\gamma_\text{PLL} = 0 \label{eqn:al9.5}
    \\&\
    i_\text{t,d}^{*} - K^\text{P}_\text{APC}(p^{*}-\tilde{p}) - K^\text{I}_\text{APC}\phi_\text{d} = 0 \label{eqn:al12}
    \\&\
    i_\text{t,q}^{*} - K^\text{P}_\text{RPC}(q^{*}-\tilde{q}) - K^\text{I}_\text{RPC}\phi_\text{q} = 0 \label{eqn:al13}
    \\&\
    v_\text{t,d} - K^\text{P}_\text{CC}(i^{*}_\text{t,d}\!-\!i_\text{t,d}) - K^\text{I}_\text{CC} \gamma_\text{d} - K^\text{F}_\text{CC}v_\text{c,d} + \omega L_\text{f} i_\text{t,q} = 0 \label{eqn:al3}
    \\&\
    v_\text{t,q} - K^\text{P}_\text{CC}(i^{*}_\text{t,q}\!-\!i_\text{t,q}) - K^\text{I}_\text{CC} \gamma_\text{q} - K^\text{F}_\text{CC}v_\text{c,q} - \omega L_\text{f} i_\text{t,d} = 0 \label{eqn:al4}
    \\&\ 
    i_\text{g,d} - i_\text{g,D}\cos(\theta_\text{PLL}) - i_\text{g,Q}\sin(\theta_\text{PLL}) = 0 \label{eqn:al10}
    \\&\
    i_\text{g,q} + i_\text{g,D}\sin(\theta_\text{PLL}) - i_\text{g,Q}\cos(\theta_\text{PLL}) = 0 \label{eqn:al11}    
    \\&\ 
    v_\text{c,d} - v_\text{c,D}\cos(\theta_\text{PLL}) - v_\text{c,Q}\sin(\theta_\text{PLL}) = 0 \label{eqn:al1}
    \\&\
    v_\text{c,q} + v_\text{c,D}\sin(\theta_\text{PLL}) - v_\text{c,Q}\cos(\theta_\text{PLL}) = 0 \label{eqn:al2}
    \\&\
    p - v_\text{c,d}i_\text{g,d} - v_\text{c,q}i_\text{g,q} = 0 \label{eqn:al7}
    \\&\ 
    q - v_\text{c,q}i_\text{g,d} + v_\text{c,d}i_\text{g,q} = 0 \label{eqn:al8}
    \\&\
    u_\text{DC}i_\text{DC} - v_\text{t,d}i_\text{t,d} - v_\text{t,q}i_\text{t,q} = 0 \label{eqn:al14}
\end{align}


