\subsection{Main Results and Related Work}

Let us summarize our results below.
\begin{enumerate}
    \item With respect to $\norm{\cdot}_1$, the problem \eqref{avoid_prob} admits a feasible solution $x$ with $\norm{x}_1 \leq (m+n)/2$, where $m = \abs{\AC}$, and we show that such solution can be constructed by a deterministic polynomial-time algorithm with $O(n \cdot m)$ operations, see Theorem \ref{approx_alg_th} of Section \nameref{approx_sec}. The inequality is the best possible, see the discussion afterward.

    This is a significant improvement over the previous $O(n \cdot m)$-time randomized algorithm of \cite{SparseILP_Gribanov}, which computes $x$ with a guaranty $\norm{x}_{1} \leq n \cdot m$. In contrast, the original approach of A.~Barvinok searches $x$ in the form $x = (1 , t, t^2, \dots, t^{n-1})$. Since, for each $a \in \AC$, $a^\top x = \sum_{i = 1}^{n} a_i \cdot t^{i-1}$ is a polynomial of degree at most $n-1$, there exists a suitable $t$ with $t \leq n \cdot m$. However, this reasoning can guaranty only $\norm{x}_1 = O\bigl((n \cdot m)^n\bigr)$. 

    % \item With respect to $\norm{\cdot}_1$, the problem \eqref{avoid_prob} can be solved exactly by an algorithm with $O\bigl(2^{n} \cdot n \cdot m\bigr)$ operations. See Theorem \ref{avoid_exp_algo_th} of Section \nameref{exact_sec};

    \item For any $p \in \bigl(\RR_{\geq 1} \cup \{\infty\}\bigr)$, the problem \eqref{avoid_prob} is $\NP$-hard with respect to any norm $\norm{\cdot}_p$, even in its \emph{homogeneous form}. See Theorem \ref{avoid_NPhard_th} of Section \nameref{exact_sec};

    \item We show that the problem to calculate the value $\abs{\PC \cap \ZZ^n}$ for a polyhedron $\PC$ defined by the system $A x \leq b$, for agiven $A \in \ZZ^{m \times n}$ and $b \in \QQ^m$, can be solved with $O\bigl( \nu^2 \cdot n^3 \cdot \Delta^3 \bigr)$ operations, where $\nu$ is the maximum size of a normal fan triangulation of $\PC$, and $\Delta$ is the maximum value of rank-order subdeterminants of $A$. It refines the $O\bigl(\nu^2 \cdot n^4 \cdot \Delta^3\bigr)$-time algorithm of \cite{SparseILP_Gribanov}. As an application, it provides a refined complexity bound for the counting problem in polyhedra of bounded codimension. More specifically, it improves the computational complexity bound for counting the number of solutions in the Unbounded Subset-Sum problem. See Subsection \nameref{motivation_sec}, more specifically, see the discussion alongside Proposition \ref{delta_counting_complexity_prop};
\end{enumerate}

It is easy to see that the guaranty $\norm{x}_1 \leq (m+n)/2$ on an existing solution $x$ of the system \eqref{avoid_sys} is the best possible.
\begin{proposition}\label{approx_alg_optimality_prop}
    There exists a family of systems \eqref{avoid_sys} such that $\norm{x}_1 \geq (m+n)/2$ for any solution $x$. 
\end{proposition}
\begin{proof}
    Fix some positive integer $k$. The desired system consists of the constraints $x_i \not= j$, for any $i \in \intint n$ and $j \in \intint[-k]{k}$. So, the total number of constraints is $m = (2k + 1) \cdot n$. It is easy to see that $\abs{x_i} \geq k + 1$, for any $i \in \intint n$ and any solution $x$ of the system. Therefore, $\norm{x}_1 \geq (k+1) \cdot n = (m + n)/2$.
\end{proof}

However, for the homogeneous form of the system \eqref{avoid_sys},
% If one does not require the existence of an efficient algorithm, 
the asymptotics of the solution quality with respect to the parameter $m$ can be slightly improved. This observation is based on the following result of I.~B{\'a}r{\'a}ny, G.~Harcos, J.~Pach, \& G.~Tardos \cite{SubspaceCovering_Barany}. Let $\BB_1$ be the unit ball with respect to $\norm{x}_1$ and $g(r)$ be a minimal number of subspaces needed to cover all points of the set $r \cdot \BB_1 \cap \ZZ^n$. 
\begin{theorem}[I.~B{\'a}r{\'a}ny, G.~Harcos, J.~Pach, \& G.~Tardos \cite{SubspaceCovering_Barany}]\label{avoid_subspace_cover_th}
    There exist absolute constants $C_1$ and $C_2$ such that
    \begin{equation*}
        C_1 \cdot \frac{1}{n^2} \cdot r^{\frac{n}{n-1}} \leq g(r) \leq C_2 \cdot 2^n \cdot r^{\frac{n}{n-1}}.
    \end{equation*}
\end{theorem}
Note that the original work \cite{SubspaceCovering_Barany} contains a  more general result concerning arbitrary convex bodies in $\RR^n$, albeit  with a  worse dependence on $n$. The  Theorem \ref{avoid_subspace_cover_th} is a straightforward adaptation of the original proof to the case of $\BB_1$.

As a corollary, it follows that the system \eqref{avoid_sys} always has a solution with an   asymptotics that is slightly better in $m$, but worse in $n$.  
\begin{corollary}\label{avoid_exist_th}
    The system \eqref{avoid_sys} has a solution $x$, such that
    $$
        \norm{x}_1 = O \bigl( n^2 \cdot m^{\frac{n-1}{n}} \bigr).
    $$
\end{corollary}

At the same time, the theorem implies that solutions of significantly smaller norm do not exist in general. In particular, it implies that our constructive bound $\norm{x}_1 \leq (m+n)/2$ is almost optimal with respect to $m$ even in the homogeneous case.
\begin{corollary}\label{avoid_nonexist_th}
    There exists a system \eqref{avoid_sys} such that, for any solution $x$, 
    $$
        \norm{x}_1 = \Omega\bigl( \frac{1}{2^n} \cdot m^{\frac{n-1}{n}} \bigr).
    $$
\end{corollary}

\section{Approximate Solution via \emph{Combinatorial Nullstellensatz}}\label{approx_sec}

The existence of a solution $x$ of \eqref{avoid_sys} of a small norm can be guarantied by the  \emph{Combinatorial Nullstellensatz} due to N.~Alon \cite{AlonNull}. 
\begin{theorem}[N.~Alon \cite{AlonNull}]\label{null_Alon_th}
    Let $f(x) \in \FF[x_1, \dots, x_n]$ be a non-zero polynomial with coefficients in the field $\FF$, and let $x_1^{d_1}  \ldots x_n^{d_n}$ be a monomial of $f$ of the largest total degree.  For $i \in \{1,2,\dots,n\}$, let $S_i \subseteq \FF$ be a set  with $\abs{S} \geq d_i + 1$. Then, there exists $y \in S_1 \times \ldots \times S_n$ such that $f(y) \not= 0$. 
\end{theorem}

\begin{proposition}\label{small_norm_via_null_prop}
    The system \eqref{avoid_sys} has a solution $y$ such that $\norm{y}_1 \leq (m+n)/2$.
\end{proposition}
\begin{proof}
    Consider a polynomial
    \begin{equation}\label{polynew}
        f(x) = \prod\limits_{(a,a_0) \in \AC} \bigl(a^\top x - a_0\bigr).
    \end{equation} and let $x_1^{d_1} \cdot \ldots \cdot x_n^{d_n}$ be its monomial of the highest total degree. Clearly, $x$ is a solution \eqref{avoid_sys} iff $f(x) \not= 0$. Define the sets
    \begin{equation*}\label{deg_sets_S}
        S_i = \bigl\{-\lceil d_i/2 \rceil, \dots, -1, 0, 1, \dots, \lceil d_i/2 \rceil \bigr\},\quad\text{for $i \in \intint n$.}
    \end{equation*}
    Note that $\abs{S_i} \geq d_i + 1$, and, for any $y \in S_1 \times \ldots \times S_n$,
    \begin{equation*}
        \norm{y}_1 \leq \lceil d_1/2 \rceil + \ldots + \lceil d_n/2 \rceil \leq (m + n)/2. 
    \end{equation*}
    Thus, Theorem \ref{null_Alon_th} implies the proposition.
\end{proof}

Unfortunately, Combinatorial Nullstellensatz is an existence proof, and comes with no efficient algorithm to find the desired vector $y$ (see, e.g., Gnang~\cite{AlonNull_Hardness}).%  it is a complicated task to construct an effective algorithm which finds $y$ satisfying the statement of Theorem \ref{null_Alon_th}. 
To this end, we propose a weaker variant of the Combinatorial Nullstellensatz, which, however, implies the same bound on the $\ell_1$-norm of $y$ in our application and, moreover, %only guarantees an existence of $y$ with $\norm{y}_1 \leq (m+n)/2$ rather than existence of $y \in S_1 \times \ldots \times S_n$. On the other hand, this new approach  
allows us to efficiently find such a vector $y$.


\begin{theorem}\label{nullalgo_Alon_th}
    Let $f \in \ZZ[x_1, \ldots, x_n]$, $m = \deg(f)$ and assume that for any tuple $(y_1, \dots, y_k)$ of $k$ integers, we can check if $f(y_1, \dots, y_k, x_{k+1}, \dots, x_n) \equiv 0$ using an oracle call.

    Then, there exists an algorithm, which computes a point $y \in \ZZ^n$ with $\norm{y}_1 \leq (m+n)/2$ and $f(y) \not= 0$. The algorithm uses at most $m + 2n$ calls to the oracle. Additionally, the solution $y$ generated by the algorithm is \emph{`lexicographically minimal'} in the following sense: $\abs{y_1}$ is minimized over all feasible points, $\abs{y_2}$ is minimized over all feasible points with $\abs{x_1} = \abs{y_1}$, and so on.
    % Moreover, we can assume that $\abs{y_1}$ is minimized over all such points.
\end{theorem}
\begin{proof}
    The algorithm consists of $n$ elementary steps, each of which eliminates one of the variables $x_i$. The first step eliminates $x_1$, the second step eliminates $x_2$, and so on. Consider the first step. Denote $S = \intint[-\lceil m/2 \rceil]{\lceil m/2 \rceil}$. For each  $y_1 \in S$, ordered in the increasing order of their absolute values, we check if  $f(y_1, x_2, \dots, x_n) \equiv 0$. Take the first value of $y_1$ such that this is not satisfied. Note that each new value of $y_1$ for which this polynomial is identically $0$, gives a new linear multiple $(x_1-y_1)$ of $f$. Since $\abs{S} > m$ and the degree of $f$ is $m$, such $y_1$ exists. %Note that we need at most $2\abs{y_1} + 1$ oracle calls to find $y_1$. 
    % Arguing indirectly, assume that $f(y_1, x_2, \dots, x_n) \equiv 0$ for all $y_1 \in S$. Then, $f(x) = g(x) \cdot \prod_{y_1 \in S} (x_1 - y_1)$, for some $g(x) \in \ZZ[x_1, \ldots, x_n]$. Since $\abs{S_1} \geq d_1 + 1$, each monomial of the maximum total degree in $f$ is divisible by $x_1^{d_1 + 1}$. This is a contradiction that proves the claim. 
    When such $y_1$ is found, we make a substitution $\hat f(x_2, \dots, x_n) = f(y_1, x_2, \dots, x_n)$. We claim that $\deg(\hat f) \leq m - (2\abs{y_1} -1)$. Indeed, the inequality is trivial when $y_1 = 0$. If $\abs{y_1} \geq 1$, then $f$ is divisible by 
    \begin{equation*}
        \prod\limits_{i = -\bigl(\abs{y_1}-1\bigr)}^{\abs{y_1}-1} (x_1 - i),
    \end{equation*}
    which proves the claim.

    The second step eliminates the variable $x_2$ in $\hat f$ using the same scheme. Acting in this manner, we find $y = (y_1, \dots, y_n)^\top \in S^n$ with $f(y_1, \dots, y_n) \not= 0$, and
    \begin{equation*}
        \sum\limits_{i = 1}^n (2 \abs{y_i} - 1) \leq m.
    \end{equation*}
    Rewriting the last inequality, we get $\norm{y}_1 \leq (m+n)/2$. In turn, the total number of oracle calls is bounded by $\sum\limits_{i = 1}^n (2 \abs{y_i} + 1) \leq m + 2n$.
\end{proof}

We shall apply Theorem~\ref{nullalgo_Alon_th} to the polynomial \eqref{polynew}. In that case, the whole procedure can be made very efficient.

