\begin{lemma}\label{avoid_inf_NPhard_lm}
    For $p = \infty$, the homogeneous form of the problem \eqref{avoid_prob} is $\NP$-hard.
\end{lemma}
\begin{proof}
     Let us reduce the classical $\NP$-hard \emph{Vertex Chromatic Number Problem} to our problem. Consider an arbitrary simple graph $G = (V, E)$ on $n$ vertices with $m$ edges. It is not hard to see that the Vertex Chromatic Number Problem with respect to $G$ can be formulated by the following way:
    \begin{gather}
        \norm{x}_\infty \to \min\notag\\
        \begin{cases}
            \forall (u,v) \in E,\quad \abs{x_u} \not= \abs{x_v}\\
            x \in \mathbb{Z}^{V}.
        \end{cases}\label{chromnum_prob}
    \end{gather}
    Here, for an optimal solution $x^*$ of the problem above, the chromatic number of $G$ is exactly $\norm{x^*}_{\infty} + 1$, and the colors are $\bigl\{0,1, \dots, \norm{x^*}_{\infty} \bigr\}$. A proper coloring  of the vertices is given by the vector $\abs{x^*}$. 

    The formulation \eqref{chromnum_prob} can be rewritten as
    \begin{gather*}
        \norm{x}_\infty \to \min\\
        \begin{cases}
            \forall (u,v) \in E,\quad x_u - x_v \not= 0\\
            \forall (u,v) \in E,\quad x_u + x_v \not= 0\\
            x \in \mathbb{Z}^{V},
        \end{cases}
    \end{gather*}
    This system is an instance of  \eqref{avoid_prob} for $p = \infty.$ It proves the $\NP$-hardness of the latter. 
    % That proves $\NP$-hardness of the latter.
\end{proof}

\begin{lemma}\label{avoid_finite_NPhard_lm}
    For any $p \in \RR_{\geq 1}$, the homogeneous form of the problem \eqref{avoid_prob} is $\NP$-hard.
\end{lemma}
\begin{proof}
     We reduce the classical $\NP$-hard \emph{Minimum Vertex Cover Problem} to our problem. Consider an arbitrary simple graph $G = (V, E)$ on $n$ vertices and with $m$ edges. We claim that the Minimum Vertex Cover Problem with respect to $G$ can be formulated as follows.
    \begin{gather*}
        \norm{x}_p^p \to \min\\
        \begin{cases}
            \forall (u,v) \in E,\quad x_u + x_v\ne 0\\
            x \in \mathbb{Z}^{V}.
        \end{cases}
    \end{gather*}
    Indeed, given an optimal solution  $x^*$ to this system,  construct a new vector $y^*$ such that $y^*_i = 0$ iff $x^*_i=0$ and $y^*_i = 1$ otherwise. First, note that $\norm{x^*}_p^p\ge \norm{y^*}_p^p$ and, second, that $y^*$ is also a solution to the system above. Indeed, if $x^*_u + x^*_v\ne 0$, then at least one of $x_u,x_v$ is not $0$, and thus $y^*_u + y^*_v\ge 1$. It implies that there is an optimal solution $x^*$ to the system above with $x^*_i\in \{0,1\}$ for all $i$. Finally, for $\{0,1\}$-solutions it is easy to see that any such solution corresponds to a vertex cover of $G$ and that, moreover, minimizing the $\ell_p$-norm is the same as minimizing the size of the cover. Since the displayed problem is an instance of \eqref{avoid_prob}, it proves $\NP$-hardness of the latter.
\end{proof}

Lemmas \ref{avoid_inf_NPhard_lm} and \ref{avoid_finite_NPhard_lm} yield
\begin{theorem}\label{avoid_NPhard_th}
    For any $p \in \bigl(\RR_{\geq 1} \cup \{\infty\}\bigr)$, the problem \eqref{avoid_prob} is $\NP$-hard.
\end{theorem}

