\subsubsection{Comparison on the degree of polynomials}

In this subsubsection, we compare the degrees of polynomials appearing in the conditions. We choose the maximal degree as an indicator for this assessment. For simplicity, we introduce the following notations:
\begin{itemize}
\item $d_\text{YHZ}$: the maximal degree of polynomials appearing in YHZ's condition;
\item $d_\text{QXY}$: the maximal degree of polynomials appearing in the new condition (produced by Algorithm \ref{alg:rpm}).
\end{itemize}


Under Assumption \ref{assumption:nonzero}, we have the following proposition.


\begin{proposition} \label{prop:maxdegree_YHZ}
 $d_{\rm YHZ}\ge3^{\lfloor{n}/{2}\rfloor}$.  
\end{proposition}

\begin{proof}
Note that when $1\le j\le \deg\tilde{G}_i-1$,
\[D_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)=\pm \operatorname*{lcoef}(\tilde{G}_i)\cdot \overline{R_{j}\left(  \tilde{G}_{i},\tilde{G}_i'\right)  }\]
Thus $\deg_a D_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)\ge\deg_a \overline{R_{j}\left(  \tilde{G}_{i},\tilde{G}_i'\right)  }$. Thereby,
\begin{align*}
d_{\rm YHZ}\ =&\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\max\Bigg(  \bigcup\limits_{i=0}^{\mu_{1}-2}\ \ \bigcup\limits_{j=\bar{\mu}_{i+1}+1}%
^{s_i}\left\{\deg_aD_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)\right\} \ \cup
\ \ \left\{\deg D_{s_{\mu_1-1}}\left(  \tilde{G}_{\mu_{1}-1},\tilde{G}_{\mu_{1}-1}'\right) \right\}\notag\\
 &\ \qquad\qquad\qquad\cup\ \bigcup\limits_{i=0}^{\mu_{1}-1}\ \bigcup_{j=1}^{\bar{\mu}_{i+1}}
 \left\{\deg_a D_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)\right\}
\Bigg)\\
\ge&\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\max\Bigg(  \bigcup\limits_{i=0}^{\mu_{1}-2}\ \ \bigcup\limits_{j=\bar{\mu}_{i+1}+1}%
^{s_i}\left\{\deg_a\overline{R_{j}\left(  \tilde{G}_{i},\tilde{G}_i'\right)  }\right\} \ \cup
\ \ \left\{\deg\overline{R_{s_{\mu_1-1}}\left(  \tilde{G}_{\mu_{1}-1},\tilde{G}_{\mu_{1}-1}'\right)  }\right\}\notag\\
 &\ \qquad\qquad\qquad\cup\ \bigcup\limits_{i=0}^{\mu_{1}-1}\ \bigcup_{j=1}^{\bar{\mu}_{i+1}}
 \left\{\deg_a D_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)\right\}
\Bigg)
\end{align*}
For the sake of simplicity, we use the following shorthand
notation:
\begin{align*}
d_{\boldsymbol{\mu}}\ =&\ \max\Bigg(  \bigcup\limits_{i=0}^{\mu_{1}-2}\ \ \bigcup\limits_{j=\bar{\mu}_{i+1}+1}%
^{s_i}\left\{\deg_a\overline{R_{j}\left(  \tilde{G}_{i},\tilde{G}_i'\right)  }\right\} \ \cup
\ \ \left\{\deg\overline{R_{s_{\mu_1-1}}\left(  \tilde{G}_{\mu_{1}-1},\tilde{G}_{\mu_{1}-1}'\right)  }\right\}\notag\\
 &\ \qquad\quad\cup\ \bigcup\limits_{i=0}^{\mu_{1}-1}\ \bigcup_{j=1}^{\bar{\mu}_{i+1}}
 \left\{\deg_a D_j\left(  \tilde{G}_{i},\tilde{G}_i'\right)\right\}
\Bigg)
\end{align*}
Then $d_{\rm YHZ}\ge\max_{\boldsymbol{\mu}\in\mathcal{M}(n)}d_{\boldsymbol{\mu}}$.

By \cite[Lemma 17-3]{2021_Hong_Yang_arxiv}, when $2\le m\le n-2$,
$d_{\boldsymbol{\mu}}\ge2n+3^{\mu_2}-4\mu_2$.
Thus
\begin{align*}
d_{\rm YHZ}\ &\ge\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}d_{\boldsymbol{\mu}}\\
 &\ge\ \max_{\substack{\boldsymbol{\mu}\in\mathcal{M}(n)\\2\le m\le n-2}}d_{\boldsymbol{\mu}}\\
 &\ge\ 2n+3^{\mu_2}-4\mu_2\\ 
 &=\ 2n+3^{\lfloor{n}/{2}\rfloor}-4\lfloor{n}/{2}\rfloor\\
 &\ge\ 3^{\lfloor{n}/{2}\rfloor}
\end{align*}
\end{proof}


For the maximal degree of polynomials in the new condition presented in this paper, we  prove the following proposition.
\begin{proposition}\label{prop:maxdegree_QXY}
When $n\ge3$, $d_{\rm QXY} = n(n-1).$
\end{proposition}

\begin{proof}

Recall \eqref{eqs:QXYcond}. We have
\begin{align*}
d_\text{QXY}\ =&\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\Bigg(\bigcup_{\substack{\boldsymbol{\gamma}\succ\boldsymbol{\bar{\mu}}\\\boldsymbol{\gamma}\in\mathcal{M}(n)}}\left\{
\deg_aR_{\boldsymbol{\gamma}}(\boldsymbol{F})\right\} \ \cup
\ \{\deg_aR_{\boldsymbol{\bar{\mu}}}(\boldsymbol{F})\}\ \cup\ \bigcup\limits_{i=0}^{\mu_{1}-1}\bigcup\limits_{j=1}^{\bar{\mu}_{i+1}}\left\{\deg_a D_j(G_i,G_{i}')\right\}\Bigg)\\
=&\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\Bigg(\max_{\substack{\boldsymbol{\gamma}\succeq\boldsymbol{\bar{\mu}}\\\boldsymbol{\gamma}\in\mathcal{M}(n)}}
\deg_aR_{\boldsymbol{\gamma}}(\boldsymbol{F}), \ \ \ \max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\Bigg)
\end{align*}
It was shown in \cite{2024_Hong_Yang:non-nested} that \[\max_{\substack{\boldsymbol{\gamma}\succeq\boldsymbol{\bar{\mu}}\\\boldsymbol{\gamma}\in\mathcal{M}(n)}}
\deg_aR_{\boldsymbol{\gamma}}(\boldsymbol{F})=2n-\mu_m\]
Thus
\begin{align*}
d_\text{QXY}\ &=\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\bigg(2n-\mu_m,\ \  \max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\bigg)\\
&=\ \max\bigg(2n-1,\ \  \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\bigg)\\
&=\ \max\bigg(2n-1,\ \  \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\max_{0\le i\le\mu_{1}-1}2\bar{\mu}_{i+1}\deg_a G_i\bigg)
\end{align*}


Note that 
\[
\deg_a G_i=\left\{
\begin{array}{ll}
1 &  \text{if $i=0;$}\\
(\bar{\mu}_1-1)+(\bar{\mu}_1+\cdots+\bar{\mu}_i) & \text{if $i>0$}. \\
\end{array}
\right.
\]
Hence we can derive that 
\begin{align*}
&\ \max_{\boldsymbol{\mu}\in\mathcal{M}(n)}\max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\\ =&\ 2\max_{\boldsymbol{\mu} \in \mathcal{M}(n)}\max\left(\bar{\mu}_{1},\ \max_{1\le i\le\mu_{1}-1}\bar{\mu}_{i+1}\big((\bar{\mu}_1-1)+(\bar{\mu}_1+\cdots+\bar{\mu}_i)\big)\right)
\end{align*}

Now we consider the following three cases.
\begin{enumerate}
\item 
When $m=1$, i.e., $\boldsymbol{\mu}=(n)$, $\bar{\mu}_1=\cdots=\bar{\mu}_{n}=1$. It follows that
\begin{align*}
&\max\left(\bar{\mu}_{1},\ \max_{1\le i\le\mu_{1}-1}\bar{\mu}_{i+1}\big((\bar{\mu}_1-1)+(\bar{\mu}_1+\cdots+\bar{\mu}_i)\big)\right)=\ \max(1,\ \max_{1\le i\le\mu_{1}-1}i)\ =\ n-1
\end{align*}
Thus,
\[\max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\ =\ 2(n-1)\ < \ 2n-1\]

\item 
When $m=n$, i.e., $\boldsymbol{\mu}=(1,\ldots,1)$, 
\[\max_{0\le i\le\mu_{1}-1}\deg_a D_{\bar{\mu}_{i+1}}(G_i,G_{i}')\ =\ \deg_a D_{\bar{\mu}_{1}}(G_0,G_{0}')\ =\ 2n>2n-1\]

\item When  $2\le m\le n-1$, i.e.,  $\boldsymbol{\mu}\notin\{(n), (1,\ldots,1)\}$, let $b=\mu_1-1$ and $c=\bar{\mu}_{\mu_1}$. Thus $\bar{\mu}_1+\cdots+\bar{\mu}_{\mu_1-1} = n-c$. From the Young tableau of $\boldsymbol{\mu}$ below,
\ytableausetup{centertableaux}
\begin{equation}\label{eq:ytableau}
n-c\left\{
\begin{array}{c}
\\[4em]
\end{array}
\right.
\begin{ytableau}
        \none & \none & \none[b+1] & \none[]& \none[] \\
        \none[\bar{\mu}_1]&\none[] &  &  & &&& \\
        \none[\bar{\mu}_2] &\none[] &  &  & && \none\\
        \none & \none&\none[$\vdots$] & \none[$\vdots$]  \\
        \none[\bar{\mu}_{\mu_1-1}]&\none[] &  &  \\
        \none[\bar{\mu}_{\mu_1}(=c)] &\none[] &  &\none 
\end{ytableau}
\end{equation}
we have $b+c\le n-c$. Now we consider the following function 
$$f(c,b) = c(b+n-c)$$
in $c$ and $b$ whose feasible region (see Fig. \ref{fig:feasible_region}) is bounded by
\[
\left\{
\begin{array}{ll}
1\le c\le n-1, & \text{a natural condition} \\
1< b+1< n, & \text{since $1<\mu_1< n$} \\
b+1 \le n-c, & \text{see \eqref{eq:ytableau}}
\end{array}
\right.\]

\begin{figure}[ht]
\centering
\includegraphics[width=0.6\textwidth]{feasible_region.eps}
\caption{The feasible region of $(c,b)$}
\label{fig:feasible_region}
\end{figure}

\noindent Then we have 
\[\dfrac{\partial f}{\partial c}\ =\ (b+n)-2c,\qquad \dfrac{\partial f}{\partial b}\ =\ c.\]
Obviously, $\dfrac{\partial f}{\partial b}\ge1$. Moreover,
\text{since $c\le \bar{\mu}_{\mu_1-1}\le n-c$ which can be deduced from \eqref{eq:ytableau}}, we derive the following:
\[\dfrac{\partial f}{\partial c}=b+\big((n-c)-c\big)\ge0\]
which indicates that $f(c,b)$ increases w.r.t. $c$ and $b$ in the feasible region. Hence, the maximal value of $f$ is achieved on the right boundary of the region, which is defined by $b+1=n-c$. Therefore, the maximal value of $f(c,b)$ over the feasible region is
\begin{align*}
f_{\max}\ =&\ \max_{c\in\{1,\ldots,n\}}f(c,n-c-1)\\
\ =&\ \max_{c\in\{1,\ldots,n\}}c(2n-2c-1)\\
\ =&\ \max_{c\in\{1,\ldots,n\}}\left(-2\Big(c-\frac{2n-1}{4}\Big)^2+\frac{(2n-1)^2}{8}\right).
\end{align*}
We consider the following two cases.
\begin{enumerate}
\item 
When $n$ is even, i.e., $n=2k$ for some integer $k\ge1$, 
\[\max_{c\in\{1,\ldots,n\}}\left(-2\Big(c-\frac{2n-1}{4}\Big)^2+\frac{(2n-1)^2}{8}\right)=\max_{c\in\{1,\ldots,n\}}\left(-2\Big(c-\frac{4k-1}{4}\Big)^2+\frac{(4k-1)^2}{8}\right).\]
The above maximal value is achieved at $c=k=\dfrac{n}{2}$, which immediately yields
\[f_{\max}=c(2n-2c-1)\Big|_{c=\frac{n}{2}}=\frac{n(n-1)}{2}.\]
In this case, $\boldsymbol{\mu}=\left(\dfrac{n}{2},\dfrac{n}{2}\right)$.

\item When $n$ is odd, i.e., $n=2k+1$ for some integer $k\ge0$, 
\[\max_{c\in\{1,\ldots,n\}}\left(-2\Big(c-\frac{2n-1}{4}\Big)^2+\frac{(2n-1)^2}{8}\right)=\max_{c\in\{1,\ldots,n\}}\left(-2\Big(c-\frac{4k+1}{4}\Big)^2+\frac{(4k+1)^2}{8}\right).\]
The above maximal value is achieved at $c=k=\dfrac{n-1}{2}$, which immediately yields
\[f_{\max}=c(2n-2c-1)\Big|_{c=\frac{n-1}{2}}=\frac{n(n-1)}{2}.\]
In this case, $\boldsymbol{\mu}=\left(\dfrac{n+1}{2},\dfrac{n-1}{2}\right)$.
\end{enumerate}
\end{enumerate}

Therefore,
\begin{align*}
d_\text{QXY}\ &=\ \max\bigg(2n,\ \  2\max_{\substack{\boldsymbol{\mu} \in \mathcal{M}(n)\\\boldsymbol{\mu}\notin\{(n),(1,\ldots,1)\}}} \bar{\mu}_{\mu_1}(\bar{\mu}_1-1+\bar{\mu}_1+\cdots+\bar{\mu}_{\mu_1-1})\bigg)\\
&=\ \max\big(2n,\ \  n(n-1) \big).
\end{align*}

Since $2n\le n(n-1)$ for $n\ge3$, we conclude that $d_{\rm QXY}\ =\ n(n-1)$.
\end{proof}

From Propositions \ref{prop:maxdegree_YHZ} and \ref{prop:maxdegree_QXY}, it is immediately seen that the maximal degree of polynomials in the condition given by YHZ's method increases in exponential scale w.r.t. $n$ while that given by QXY's method shows an increase in polynomial scale.
Furthermore, with the help of Propositions \ref{prop:maxdegree_YHZ} and \ref{prop:maxdegree_QXY}, one can easily show the following proposition.

\begin{proposition}
When $n\ge8$, $d_{\rm YHZ}\ge d_{\rm QXY}$.
\end{proposition}

In Table \ref{tab:comparison_maxdeg}, we list the two numbers, i.e., $d_{\rm YHZ}$ and $d_{\rm QXY}$, for $n=3,\ldots,8,$ while
Fig. \ref{fig:comparison_maxdeg} shows the trend of the two numbers as $n$ increases. From Table \ref{tab:comparison_maxdeg} and
Fig. \ref{fig:comparison_maxdeg}, we make the following observations.





\begin{itemize}
\item 
When $d< 6$, $d_{\rm YHZ}\le d_{\rm QXY}$ and their differences is relatively small (no more than 2, see Table \ref{tab:comparison_maxdeg}). 
Roughly speaking, $d_{\rm QXY}\approx d_{\rm YHZ}$.

\item  When $n$ surpasses $6$, $d_{\rm QXY}$ is significantly smaller than $d_{\rm YHZ}$ (see Fig. \ref{fig:maxdeg}).  
 When $n\ge 4$, the ratio $\dfrac{d_{\rm YHZ}}{d_{\rm QXY}}$ grows as $n$ increases (see Fig. \ref{fig:maxdeg_ratio}). Therefore, the size of the polynomial with the maximal degree in YHZ's method becomes even bigger than that in the proposed method. Hence, it is expected that when $n$ is large enough, the new method will be  far more efficient than YHZ's method.

\end{itemize}


