\section*{Appendix A.}

Appendix A is dedicated to proving Proposition \ref{prop:sres_prem}. For this purpose, we need the following lemma which is a specialization of \cite[Lemma 29]{2024_Hong_Yang}. 

\begin{lemma}\label{lem:R_lincomb}
Given $P\in\mathbb{R}[x]$ with degree $n$, let $\boldsymbol{F} = (P^{(0)},P^{(1)},\ldots,P^{(t)})$ and $\boldsymbol{\delta} = (\delta_{1}, \ldots, \delta_{t})\in\mathcal{P}(n,t)$. Then we have
$R_{\boldsymbol{\delta}}\in\langle \boldsymbol{F}\rangle$. More explicitly, 
$$R_{\boldsymbol{\delta}} = \sum_{u = 0}^{t}\sum_{v = 0}^{\delta_{u} - 1}c_{u,v}x^{v}P^{(u)}$$
where $\delta_0$ is determined as in \eqref{eqs:delta0}, $c_{u,\delta_{u} - 1}=(-1)^{\sigma}a_n^{\tau}\overline{R_{\boldsymbol{\delta}-\boldsymbol{e}_{u}}}$ for $u\ge1$  and 
\[\sigma=1+\delta_u+\cdots+\delta_t,\ \ \text{and}\ \ \ 
\tau=\left\{
\begin{array}{ll}
1 &\text{if}\ d_u+\delta_u>\max\limits_{\substack{\delta_i\ne0\\i\ne 0,u}}(d_i+\delta_i);\\
0&\text{otherwise}.
\end{array}\right.\]
\end{lemma}

\begin{proof}[Proof of Proposition \ref{prop:sres_prem}]
Recall $\boldsymbol{\delta}=(\delta_1,\ldots,\delta_t)$ satisfies $|\boldsymbol{\delta}|\le n$, $\delta_t\ge 1$ and $\delta_j>\delta_{j+1}$ for some $1\le j<t$. 
Let $\boldsymbol{\gamma}=\boldsymbol{\delta}-\boldsymbol{e}_j$ and $\boldsymbol{\gamma'}=\boldsymbol{\delta}-\boldsymbol{e}_t$. 
By Lemma \ref{lem:R_lincomb},
\begin{align*}
R_{\boldsymbol{\gamma}}=\sum_{u=0}^{t}\sum_{v = 0}^{\gamma_{u} - 1}c_{u,v}x^{v}P^{(u)},\quad R_{\boldsymbol{\gamma'}}=\sum_{u=0}^{t}\sum_{v = 0}^{\gamma_{u}' - 1}c'_{u,v}x^{v}P^{(u)}
\end{align*}
where $\gamma_0$ and $\gamma_0'$ are determined as in \eqref{eqs:delta0},
and 
\begin{align}
c_{t,\gamma_t-1}&=(-1)^{1+\gamma_t}\overline{R_{\boldsymbol{\gamma}-\boldsymbol{e}_t}}\notag\\
&\quad\text{($\tau=0$ is implied by $\gamma_t<\gamma_1$ and $d_t=n-t<n-1=d_1$)}\notag\\
&=(-1)^{1+\delta_t}\overline{R_{\boldsymbol{\delta}-\boldsymbol{e}_j-\boldsymbol{e}_t}(\boldsymbol{F})},\hspace{9em}\text{(since $\gamma_t=\delta_t$)}\label{eq:lc_t}\\
c'_{j,\gamma_j'-1}&=(-1)^{1+\gamma'_j+\cdots+\gamma'_t}a_n^{\tau}\overline{R_{\boldsymbol{\gamma'}-\boldsymbol{e}_j}}\notag\\
&=(-1)^{\delta_j+\cdots+\delta_t}a_n^{\tau}\overline{R_{\boldsymbol{\delta}-\boldsymbol{e}_t-\boldsymbol{e}_j}}
\label{eq:lc_j}\\
&\hspace{1em}\ \text{(since $\gamma_j'=\delta_j$ for $j<t$ and $\gamma_t'=\delta_t-1$)},\notag
\end{align}
where $\tau=\left\{
\begin{array}{ll}
1 &\text{if}\ j=1;\\
0&\text{otherwise}
\end{array}\right.
$ (which is a specialization of $\tau$ in Lemma \ref{lem:R_lincomb}).

Since $\gamma_t=\delta_t$ and $\gamma_j'=\delta_j$, the above linear combinations can be further rewritten as
\begin{align}
&c_{t,\delta_t-1}x^{\delta_t-1}P^{(t)}=R_{\boldsymbol{\gamma}}-\sum_{(u,v)\in C_1}c_{u,v}x^{v}P^{(u)},\label{eqs:C_t}\\ &c'_{j,\delta_j-1}x^{\delta_j-1}P^{(j)}=R_{\boldsymbol{\gamma'}}-\sum_{(u,v)\in C_2}c'_{u,v}x^{v}P^{(u)}.\label{eqs:C_j}
\end{align}
where 
\begin{align*}
C_1&=\{(u,v):\,0\le u\le t, 0\le v\le \gamma_{u}-1\}\backslash\{(t,\delta_t-1)\},\\
C_2&=\{(u,v):\,0\le u\le t, 0\le v\le \gamma'_{u}-1\}\backslash\{(j,\delta_j-1)\}.\\
\end{align*}
Now we consider $R_{\boldsymbol{\delta}}$, which is
\begin{align*}
R_{\boldsymbol{\delta}}=\operatorname{dp}(&x^{\delta_1-2}P^{(0)},\ldots,x^0P^{(0)},x^{\delta_1-1}P^{(1)},\ldots,x^0P^{(1)},\\
&\ldots,x^{\delta_j-1}P^{(j)},\ldots,x^0P^{(j)},\ldots\ldots,x^{\delta_t-1}P^{(t)},\ldots,x^0P^{(t)}).
\end{align*}
For the sake of simplicity, we introduce the following notations. Let
$$P_{u,v} = x^vP^{(u)}, Q_{u,v} = P_{u,v-1},\dots,P_{u,0}.$$ 
Then we have 
\begin{align*}
R_{\boldsymbol{\delta}} &= \operatorname*{dp}(Q_{0,\delta_1-1},Q_{1,\delta_1},\dots,Q_{j,\delta_j},\dots,Q_{t,\delta_t},\dots,Q_{n,\delta_n}) \\
&=\operatorname*{dp}(Q_{0,\delta_1-1},Q_{1,\delta_1},\dots,\underbrace{P_{j,\delta_j-1},Q_{j,\delta_j-1}}_{Q_{j,\delta_j}},\dots,\underbrace{P_{t,\delta_t-1},Q_{t,\delta_t-1}}_{Q_{t,\delta_t}},\dots,Q_{n,\delta_n}).
\end{align*}
Consider $c_{t,\delta_t-1}c'_{j,\delta_j-1}R_{\boldsymbol{\delta}}$. We derive the following:
\begin{align*}
&c_{t,\delta_t-1}c'_{j,\delta_j-1}R_{\boldsymbol{\delta}} \\
=\ &\operatorname*{dp}(Q_{0,\delta_1-1},Q_{1,\delta_1},\dots,c'_{j,\delta_j-1}P_{j,\delta_j-1},Q_{j,\delta_j-1},\dots,c_{t,\delta_t-1}P_{t,\delta_t-1},Q_{t,\delta_t-1},\dots,Q_{n,\delta_n})\\
&\hspace{25em}(\text{pushing $c_{t,\delta_t-1}c'_{j,\delta_j-1}$ into $\operatorname*{dp}$})\\
=\ &\operatorname*{dp} (Q_{0,\delta_1-1},Q_{1,\delta_1},\dots,R_{\boldsymbol{\delta}-\boldsymbol{e}_t},Q_{j,\delta_j-1},\dots,R_{\boldsymbol{\delta}-\boldsymbol{e}_j},Q_{t,\delta_t-1},\dots,Q_{n,\delta_n}) \\
&\quad(\text{using $\eqref{eqs:C_t}$--$\eqref{eqs:C_j}$ and the multi-linearity of determinant polynomial to simplify $R_{\boldsymbol{\delta}}$})\\
=\ &(-1)^{\delta_j+\dots+\delta_{t-1}} \operatorname*{dp}(Q_{0,\delta_1-1},Q_{1,\delta_1},\dots,Q_{j,\delta_j-1},\dots,Q_{t,\delta_t-1},\dots,Q_{n,\delta_n},R_{\boldsymbol{\delta}-\boldsymbol{e}_j},R_{\boldsymbol{\delta}-\boldsymbol{e}_t}) \\
&\hspace{22em}(\text{moving $R_{\boldsymbol{\delta}-\boldsymbol{e}_j}$ and $R_{\boldsymbol{\delta}-\boldsymbol{e}_t}$ to the end})\\
=\ &(-1)^{\delta_j+\dots+\delta_{t-1}}a_n^{\tau}\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_j-\boldsymbol{e}_t}} \operatorname*{dp}(R_{\boldsymbol{\delta}-\boldsymbol{e}_j},R_{\boldsymbol{\delta}-\boldsymbol{e}_t})\
\hspace{3.5em}(\text{using the block structure of dp})
\end{align*}
where $$\tau=\left\{
\begin{array}{ll}
1 &\text{if}\ j=1;\\
0&\text{otherwise}.
\end{array}\right.
$$




%\begin{align*}
%c_{t,\delta_t-1}c'_{j,\delta_j-1}R_{\boldsymbol{\delta}}(\boldsymbol{F})=&\operatorname{dp}(x^{\delta_1-2}P^{(0)},\ldots,x^0P^{(0)},x^{\delta_1-1}P^{(1)},\ldots,x^0P^{(1)},\\
%&\qquad\ \ \ldots,\underline{c'_{j,\delta_j-1}x^{\delta_j-1}P^{(j)}},c'_{j,\delta_j-2}x^{\delta_j-2}P^{(j)},\ldots,x^0P^{(j)},\\
%&\qquad\ \ \ldots,\underline{c_{t,\delta_t-1}x^{\delta_t-1}P^{(t)}},c_{t,\delta_t-2}x^{\delta_t-2}P^{(t)},\ldots,x^0P^{(t)})\\
%=&\operatorname{dp}(x^{\delta_1-2}P^{(0)},\ldots,x^0P^{(0)},x^{\delta_1-1}P^{(1)},\ldots,x^0P^{(1)},\\
%&\qquad\ \ \ldots,\underline{R_{\boldsymbol{\gamma'}}(\boldsymbol{F})},c'_{j,\delta_j-2}x^{\delta_j-2}P^{(j)},\ldots,x^0P^{(j)},\\
%&\qquad\ \ \ldots,\underline{R_{\boldsymbol{\gamma}}(\boldsymbol{F})},c_{t,\delta_t-2}x^{\delta_t-2}P^{(t)},\ldots,x^0P^{(t)})\\
%=&(-1)^{\sigma}\operatorname{dp}(x^{\delta_1-2}P^{(0)},\ldots,x^0P^{(0)},x^{\delta_1-1}P^{(1)},\ldots,x^0P^{(1)},\\
%&\qquad\ \ \ldots,c'_{j,\delta_j-2}x^{\delta_j-2}P^{(j)},\ldots,x^0P^{(j)},\\
%&\qquad\ \ \ldots,c_{t,\delta_t-2}x^{\delta_t-2}P^{(t)},\ldots,x^0P^{(t)},\underline{R_{\boldsymbol{\gamma}}(\boldsymbol{F})},\underline{R_{\boldsymbol{\gamma'}}(\boldsymbol{F})})\\
%=&(-1)^{\sigma}a_n^{\delta_1-1-\gamma_0}s_{\delta-e_j-t_t}\operatorname{dp}(R_{\boldsymbol{\gamma}}(\boldsymbol{F}),R_{\boldsymbol{\gamma'}}(\boldsymbol{F}))
%\end{align*}
%where $\sigma=\left((\delta_j-1)+\sum_{\ell=j+1}^{t-1}\delta_{\ell}+\delta_t\right)+(\delta_t-1)$.
Now we substitute \eqref{eq:lc_t} and \eqref{eq:lc_j} into the first line of the equation and obtain
\begin{equation}\label{eqs:2bcancelled}
(-1)^{\delta_j+\dots+\delta_{t-1}+1}a_n^{\tau}\left(\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_j-\boldsymbol{e}_t}(\boldsymbol{F})}\right)^{2} R_{\boldsymbol{\delta}}(\boldsymbol{F})=(-1)^{\delta_j+\dots+\delta_{t-1}}a_n^{\tau}\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_j-\boldsymbol{e}_t}(\boldsymbol{F})} \operatorname*{dp}(R_{\boldsymbol{\delta}-\boldsymbol{e}_j},R_{\boldsymbol{\delta}-\boldsymbol{e}_t}) \end{equation}
Note that $\boldsymbol{\delta}$ is a decreasing vector and so is $\boldsymbol{\delta}- \boldsymbol{e}_t-\boldsymbol{e}_j$, which implies that for some value of $a_{i}$'s, $\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_t-\boldsymbol{e}_j}(\boldsymbol{F})}\ne0$. Hence $\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_t-\boldsymbol{e}_j}(\boldsymbol{F})}$ is a nonzero polynomial in terms of $a_i$'s. Therefore, after canceling the common factors from both sides of \eqref{eqs:2bcancelled}, we have 
\[-\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_t-\boldsymbol{e}_j}(\boldsymbol{F})}R_{\boldsymbol{\delta}}(\boldsymbol{F})=\operatorname{dp}(R_{\boldsymbol{\gamma}}(\boldsymbol{F}),R_{\boldsymbol{\gamma'}}(\boldsymbol{F})).\]
Note that 
\begin{align*}
\deg R_{\boldsymbol{\gamma}}(\boldsymbol{F})&=n-|\boldsymbol{\gamma}|=n-|\boldsymbol{\delta}|+1,\\
\deg R_{\boldsymbol{\gamma'}}(\boldsymbol{F})&=n-|\boldsymbol{\gamma'}|=n-|\boldsymbol{\delta}|+1.
\end{align*}
which implies $\deg R_{\boldsymbol{\gamma}}(\boldsymbol{F})=\deg R_{\boldsymbol{\gamma'}}(\boldsymbol{F})$. Therefore,  
we deduce that
$$\operatorname{dp}(R_{\boldsymbol{\gamma}}(\boldsymbol{F}),R_{\boldsymbol{\gamma'}}(\boldsymbol{F}))=-\operatorname*{prem}(R_{\boldsymbol{\gamma}}(\boldsymbol{F}),R_{\boldsymbol{\gamma'}}(\boldsymbol{F})) $$
which indicates that
\[\overline{R_{\boldsymbol{\delta}- \boldsymbol{e}_j-\boldsymbol{e}_t}(\boldsymbol{F})}R_{\boldsymbol{\delta}}(\boldsymbol{F})=\operatorname*{prem}(R_{\boldsymbol{\delta}-\boldsymbol{e}_j}(\boldsymbol{F}),R_{\boldsymbol{\delta}-\boldsymbol{e}_t}(\boldsymbol{F})).\]
\end{proof}

\section*{Appendix B.}
Given a   polynomial $P$, the repeated gcd of $P$ and $P'$ is defined as $(\tilde{G}_1,\ldots,\tilde{G}_n)$ where 
\[\tilde{G}_{i} =\gcd(\tilde{G}_{i-1},\tilde{G}'_{i-1})\]
with
$\tilde{G}_{0}:=P$.
In this paper, we use the incremental gcds of $P^{(0)},P^{(1)},\ldots$ instead of repeated gcds. In the appendix, we provide a detailed proof on their equivalence. 


\begin{lemma}\label{lem:equiv_rpgcd_icgcd}
 Let $G_0=P$. Then for $i\ge0$, we have $G_{i}\sim \tilde{G}_{i} $.
\end{lemma}

\begin{proof}
 Without loss of generality, we assume 
 $$ P = a_n\prod_{k = 1}^{m} (x - r_{k})^{\mu_{k}}. $$
 To prove
$G_{i} \sim \tilde{G}_{i}$,
 we only need to show
 \begin{itemize}
 \item $G_{i} \sim \prod_{\mu_{k} > i}^{ } (x - r_{k})^{\mu_{k} - i}$, and
 \item $\tilde{G}_{i} \sim \prod_{\mu_{k} > i}^{ } (x - r_{k})^{\mu_{k} - i},$
 \end{itemize}
 whose proof will be given in an inductive manner.

 {\bf Base case.}
 When $i = 0$, we have
 \[
 G_{0} =\tilde{G}_{0} = P =a_{n}  \prod_{\mu_{k} > 0}^{ } (x - r_{k})^{\mu_{k}}
 \]
 which is obviously true.

{\bf Induction step.} 
 We assume the claim holds when $i = j$, i.e.
 \begin{align*}
 G_{j} &= \gcd(G_{j - 1} , P^{(j)})\sim \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j},  \\
 \tilde{G}_{j} &= \gcd(\tilde{G}_{j - 1}, \tilde{G}'_{j - 1})\sim \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j} .
 \end{align*}
 Then for $i = j + 1$, 
 \[
G_{j + 1} = \gcd(G_{j}, P^{(j + 1)}),\qquad 
\tilde{G}_{j + 1} = \gcd( \tilde{G}_{j},  \tilde{G}'_{j}) .
 \]
 Next we deduce the expressions for $G_{j+1}$ and $\tilde{G}_{j + 1}$, respectively.

By assumption, $G_{j} \sim \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}$.
Obviously,  we have
\begin{itemize}
\item $ \prod_{\mu_{k} > j + 1}^{}(x - r_{k})^{\mu_{k} - (j + 1)} \mid  G_{j} $, and
\item when $\mu_{k} > j$,
 $$ (x - r_{k})^{\mu_{k}}\mid P^{(0)}, (x - r_{k})^{\mu_{k} - 1}\mid P^{(1)}, \ldots, (x - r_{k})^{\mu_{k} - j}\mid P^{(j)} $$
\end{itemize}
Next we show that $ \prod_{\mu_{k} > j + 1}^{}(x - r_{k})^{\mu_{k} - (j + 1)} \mid  P^{(j + 1)} $. 
The key for verifying the claim is the observation that when $\mu_{k} > j + 1$, $$P^{(j + 1)}(r_{k}) = \cdots = P^{(\mu_{k} - 1)}(r_{k}) = 0,$$
but $P^{(\mu_{k})}(r_{k}) \neq 0$, which indicates that
 $ x = r_{k} $ is the multiple roots of $P^{(j + 1)}(x)$ with multiplicity  $\mu_{k} - (j + 1) $.  Thereby, $(x - r_{k})^{\mu_{k} - (j + 1)}\mid P^{(j + 1)}(x)$. Moreover, we also have $(x - r_{k})^{\mu_{k} - j}\nmid P^{(j + 1)}$. Hence


 $$ G_{j + 1} = \gcd(G_{j} , P^{(j + 1)}) \sim \prod_{\mu_{k} > j + 1}^{}(x - r_{k})^{\mu_{k} - (j + 1)} $$


Again, by assumption, $\tilde{G}_{j} \sim \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}$.
Thus
 \begin{align*}
\tilde{G}'_{j}\sim \left( \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}\right)' &= \sum_{\mu_{k} > j}\left((\mu_{k} - j)(x - r_{k})^{\mu_{k} - j - 1} \prod_{\underset{\mu_{\ell} > j}{\ell \neq k} }^{}(x - r_{\ell})^{\mu_{\ell} - j}\right) \\
 &= \left(\sum_{\mu_k > j}^{}(\mu_k - j)\prod_{\underset{\mu_{\ell} > j}{\ell \neq k}}(x - r_{\ell})\right) \left(\prod_{\mu_{k} > j}^{}(x - r_{k})^{\mu_{k} - j - 1} \right).
 \end{align*}
 It follows that
 \begin{align*}
 \tilde{G}_{j + 1} &= \gcd( \tilde{G}_{j},  \tilde{G}'_{j}) \\
 &\sim\gcd \left( \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}, \left( \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}\right)'\right) \\
\\
&=\gcd \left( \prod_{\mu_{k} > j}^{ } (x - r_{k})^{\mu_{k} - j}, \left(\sum_{\mu_k > j}^{}(\mu_k - j)\prod_{\underset{\mu_{\ell} > j}{\ell \neq k}}(x - r_{\ell})\right) \left(\prod_{\mu_{k} > j}^{}(x - r_{k})^{\mu_{k} - j - 1} \right)\right)\\
&=\gcd \left( \prod_{\mu_{k} > j}^{ } (x - r_{k})^{}, \sum_{\mu_k > j}(\mu_k - j)\prod_{\underset{\mu_{\ell} > j}{\ell \neq k}}(x - r_{\ell})\right)\cdot \left(\prod_{\mu_{k} > j}^{}(x - r_{k})^{\mu_{k} - j - 1} \right).
\end{align*}
It remains to show that
\[\gcd \left( \prod_{\mu_{k} > j}(x - r_{k}), \sum_{\mu_k > j}(\mu_k - j)\prod_{\underset{\mu_{\ell} > j}{\ell \neq k}}(x - r_{\ell})\right)=1\]
which can be proved with the following verification
$$\left(\sum_{\mu_{k} > j}^{}(\mu_{k} - j)\prod_{\underset{\mu_{l} > j}{l \neq k}}(x - r_{\ell})\right)\Bigg|_{x=r_u} =(\mu_{u} - j)\prod_{\underset{\mu_{\ell} > j}{\ell \neq k}}(r_{u} - r_{\ell}) \neq 0$$
for $u\in\{\mu_k:\,\mu_k>j\}$. Hence 
\[\tilde{G}_{j + 1} \sim\prod_{\mu_{k} > j}^{}(x - r_{k})^{\mu_{k} - j - 1}\sim G_{j+1}. \]
\end{proof}

