$H \subseteq T \subseteq Q$ and $u \in Q\backslash T$.
\end{definition}

\begin{definition}[Supermodularity]\label{def:super}
A set function $f:2^{Q}\rightarrow \mathbb{R}$ is said to be supermodular if
\begin{equation*}\label{supermod}
f(H \cup \{u\}) - f(H) \leq f(T\cup \{u\}) - f(T)
\end{equation*}
 holds for all
$H \subseteq T \subseteq Q$ and $u \in Q\backslash T$.
