\begin{algorithm}[tb]
\begin{small}
	\caption{\textsc{Deter}$(\calG, S_1, S_0, Q, k)$}
    \label{alg:det}
	\Input{
		A connected graph $\calG=(V,E)$;
        a candidate edge set $Q=(V\times V)\backslash E$;
        an integer $1 \leq k \leq |Q|$\\
	}
	\Output{
		A subset $T\subseteq Q$ with $|T|=k$
	}
Compute $\LL^{\dag}$\;
Compute $\LL^{2\dag}$\;
Initialize solution $T = \emptyset$ \;
\For{$i = 1$ to $k$}{
Compute $\Delta(e)= K(\calG)-K(\{e\})$ for each $e \in Q$\;
Select $e_i$ s. t. $e_i \gets \mathrm{arg\, max}_{e \in Q} \Delta(e)$\;
Update solution $T \gets T \cup \{ e_i \}$ \;
Update the graph $\calG \gets \calG(V, E \cup \{ e_i \})$ \;
Update $\LL^{\dag} \gets \LL^{\dag} - \frac{ \LL^\dag\bb_e \bb_e^\top\LL^\dag }{1+\bb_e^\top \LL^\dag \bb_e}$\;
Update $\LL^{2\dag} \gets \LL^{2\dag} + \frac{\LL^\dag \bb_e \bb_e^\top\LL^{2\dag}\bb_e\bb_e^\top \LL^\dag}{(1+\bb_e^\top\LL^\dag \bb_e)^2} - \frac{\LL^{2\dag}\bb_e\bb_e^\top \LL^\dag}{1+\bb_e^\top\LL^\dag \bb_e} - \frac{\LL^{\dag}\bb_e\bb_e^\top \LL^{2\dag}}{1+\bb_e^\top\LL^\dag \bb_e}$\;

Update the candidate edge set $Q \gets Q \backslash  \{e_i\} $ \;}
\Return $T$.
\end{small}
\end{algorithm}
